CREATE OR REPLACE FUNCTION private.closure_redaction_scope_v5(r text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
 if r=ANY(ARRAY['private.work_taxonomy_review_outbox_v1','private.work_taxonomy_pending_reviews_v1','private.work_taxonomy_gemini_turn_hints_v1','private.work_taxonomy_admissions_v1','private.work_taxonomy_review_batches_v1','private.work_taxonomy_related_acceptances','private.taxonomy_confirmed_worker_modes_v1','private.work_taxonomy_worker_capabilities','private.worker_execution_mode_choices','private.work_taxonomy_need_skills','private.work_taxonomy_need_snapshots','private.work_taxonomy_need_bindings_v1','private.work_taxonomy_worker_bindings_v1','private.dev_phase1_20261014_worker_capabilities_snapshot','private.dev_phase1_20261014_opportunity_snapshot','private.dev_phase1_20261014_dispatch_snapshot','private.dev_test101_owner_worker_profile_backup','private.dev_test101_owner_profile_backup_20261014','private.dev_worker_profile_reset_snapshots_v1','private.dev_phase1_20261014_needs_snapshot']::text[]) then return private.closure_taxonomy_scope_v1(r);end if;
 if not(r=any(private.closure_redaction_relations_v5())) then raise exception 'ERASURE_RELATION_NOT_ADMITTED';end if;
 return case
 when r='public.agreement_invalidations_v1' then
  't.agreement_id in(select id from public.agreements where requester_account_id=$1 or worker_account_id=$1)'
 when r='public.app_accounts' then 't.id=$1'
 when r in('public.app_profiles','public.ai_conversations','public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'private.requester_identity_commands','private.worker_ai_saves','private.ai_task_review_commands','private.ai_task_reviews','private.worker_ai_reviews',
  'private.worker_ai_sessions','private.ai_need_turn_commands','private.worker_ai_turns','private.need_draft_save_commands','private.qa_ai_commands',
  'private.data_export_artifacts','public.data_export_requests','private.owned_media_assets','private.agreement_photo_uploads_v5','private.agreement_voice_uploads_v1',
  'private.retention_jobs','private.retention_holds','private.support_commands_v5','private.support_grant_commands_v5',
  'private.group_message_visibility_v5','private.ai_test_accounts_v5','private.support_operator_grants_v5','private.support_read_markers_v5','private.account_lineage_v5','private.account_lineage_events_v5') then 't.account_id=$1'
 when r='private.agreement_review_comments_v1' then 't.author_account_id=$1' when r in('private.need_edit_commands','private.need_publish_commands','private.remaining_search_close_commands') then 't.requester_account_id=$1'
 when r in('private.response_submit_commands','private.response_withdraw_commands','private.response_revision_resolution_commands',
  'public.marketplace_responses','public.worker_match_preferences','private.worker_calendar_events','public.opportunity_deliveries') then 't.worker_account_id=$1'
 when r in('public.profile_availability_rules','public.profile_availability_windows') then 't.profile_id in(select id from public.app_profiles where account_id=$1)'
 when r='private.worker_calendar_serialization' then 't.worker_profile_id in(select id from public.app_profiles where account_id=$1)'
 when r in('public.need_sensitive','public.need_geography','public.need_requirement_details','private.need_revision_events','private.need_publication_decisions',
  'private.dispatch_schedule','public.dispatch_rounds') then 't.need_id in(select id from public.needs where requester_account_id=$1)'
 when r='public.needs' then 't.requester_account_id=$1'
 when r in('private.response_application_snapshots','public.marketplace_response_versions') then 't.response_id in(select id from public.marketplace_responses where worker_account_id=$1)'
 when r='private.preselection_qa_questions' then 't.asker_account_id=$1'
 when r='private.preselection_qa_answer_versions' then 't.answered_by_account_id=$1'
 when r='private.preselection_qa_policy_decisions' then
  '(t.question_id in(select id from private.preselection_qa_questions where asker_account_id=$1) or t.need_id in(select id from public.needs where requester_account_id=$1) or t.id in(select policy_decision_id from private.qa_ai_commands where account_id=$1))'
 when r='private.preselection_qa_materiality_decisions' then
  '(t.question_id in(select id from private.preselection_qa_questions where asker_account_id=$1) or t.need_id in(select id from public.needs where requester_account_id=$1) or t.id in(select materiality_decision_id from private.qa_ai_commands where account_id=$1))'
 when r in('private.preselection_qa_commands','private.account_block_commands','private.agreement_location_commands','private.agreement_location_points') then 't.actor_account_id=$1'
 when r in('public.agreement_messages','private.group_messages_v5') then 't.sender_account_id=$1'
 when r='public.agreement_change_proposals' then 't.agreement_id in(select id from public.agreements where $1 in(requester_account_id,worker_account_id))'
 when r='public.agreement_versions' then 't.agreement_id in(select id from public.agreements where $1 in(requester_account_id,worker_account_id))'
 when r='public.agreement_execution' then 't.problem_opened_by=$1'
 when r='public.access_grants' then '$1 in(t.granted_by_account_id,t.granted_to_account_id)'
 when r in('public.notification_preferences','public.notification_push_devices') then 't.user_id=$1'
 when r='public.notification_push_attempts' then 't.delivery_id in(select id from public.notification_deliveries where recipient_user_id=$1) or t.device_id in(select id from public.notification_push_devices where user_id=$1)'
 when r='public.notification_deliveries' then 't.recipient_user_id=$1'
 when r='public.user_activity_events' then 't.recipient_user_id=$1 or t.entity_id in(select id from public.needs where requester_account_id=$1)'
 when r='private.marketplace_audit_log' then 't.actor_user_id=$1 or t.entity_id in(select id from public.needs where requester_account_id=$1) or t.entity_id in(select id from public.marketplace_responses where worker_account_id=$1)'
 else null end;
end $function$;

CREATE OR REPLACE FUNCTION private.closure_redaction_patch_v5(r text, t jsonb, a uuid, g uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p jsonb:='{}';k text;h text;ag public.agreements;terms jsonb;
begin
 if r is null or t is null or a is null or g is null or not(r=any(private.closure_redaction_relations_v5()))
 then raise exception 'ERASURE_RELATION_NOT_ADMITTED';end if;
 if r=ANY(ARRAY['private.work_taxonomy_review_outbox_v1','private.work_taxonomy_pending_reviews_v1','private.work_taxonomy_gemini_turn_hints_v1','private.work_taxonomy_admissions_v1','private.work_taxonomy_review_batches_v1','private.work_taxonomy_related_acceptances','private.taxonomy_confirmed_worker_modes_v1','private.work_taxonomy_worker_capabilities','private.worker_execution_mode_choices','private.work_taxonomy_need_skills','private.work_taxonomy_need_snapshots','private.work_taxonomy_need_bindings_v1','private.work_taxonomy_worker_bindings_v1','private.dev_phase1_20261014_worker_capabilities_snapshot','private.dev_phase1_20261014_opportunity_snapshot','private.dev_phase1_20261014_dispatch_snapshot','private.dev_test101_owner_worker_profile_backup','private.dev_test101_owner_profile_backup_20261014','private.dev_worker_profile_reset_snapshots_v1','private.dev_phase1_20261014_needs_snapshot']::text[]) then return private.closure_taxonomy_patch_v1(r,t,a,g);end if;
 if r='public.agreement_invalidations_v1' then
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
 h:=encode(extensions.digest(convert_to('AF-D22:ERASED:'||r||':'||coalesce(t->>'id',t->>'client_request_id',t->>'conversation_id',t->>'review_id',t->>'account_id','subject'),'UTF8'),'sha256'),'hex');
 -- Support command receipts are metadata only. A related scoped case keeps its
 -- exact recovery/hash contract until that exception is resolved; no narrative
 -- is copied into the redaction ledger. Cancelled opaque tombstones stay usable.
 if r in('private.support_commands_v5','private.support_grant_commands_v5') then return null;end if;
 if r in('public.ai_conversations','public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.worker_ai_sessions','private.ai_task_reviews','private.worker_ai_reviews','private.need_draft_save_commands')
 and exists(select 1 from private.retention_holds where account_id=a and active and conversation_id=
  case when r='public.ai_conversations' then (t->>'id')::uuid else (t->>'conversation_id')::uuid end) then return null;end if;
 if r='private.ai_task_review_commands' and exists(select 1 from private.ai_task_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='private.worker_ai_saves' and exists(select 1 from private.worker_ai_reviews v join private.retention_holds h on h.account_id=v.account_id and h.conversation_id=v.conversation_id and h.active
  where v.account_id=a and v.id=(t->>'review_id')::uuid) then return null;end if;
 if r='public.ai_structured_facts' then
  if t->'superseded_by'<>'null'::jsonb then return jsonb_build_object('operation','UPDATE','patch',jsonb_build_object('superseded_by',null));end if;
  if exists(select 1 from public.ai_structured_facts where superseded_by=(t->>'id')::uuid) then return null;end if;
 end if;
 if r in('public.ai_messages','public.ai_structured_facts','public.ai_action_proposals',
  'public.need_sensitive','public.need_geography','public.need_requirement_details',
  'private.data_export_artifacts','public.notification_push_attempts','public.notification_deliveries',
  'public.notification_push_devices','public.notification_preferences','public.opportunity_deliveries',
  'private.dispatch_schedule','public.access_grants','public.profile_availability_rules','public.profile_availability_windows',
  'public.worker_match_preferences','private.worker_calendar_events','private.worker_calendar_serialization',
  'private.support_read_markers_v5','private.group_message_visibility_v5','private.agreement_review_comments_v1') then
  if r='private.data_export_artifacts' and exists(select 1 from storage.objects where bucket_id='data-export-artifacts' and name=t->>'object_path')
  then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r='private.agreement_voice_uploads_v1' then
  if t->>'dispatch_state'='DISPATCHING' then raise exception 'ERASURE_PRODUCER_UNSETTLED';end if;
  if exists(select 1 from storage.objects where bucket_id='agreement-voice' and name=t->>'storage_path') then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r in('private.owned_media_assets','private.agreement_photo_uploads_v5') then
  if t->>'dispatch_state'='DISPATCHING' then raise exception 'ERASURE_PRODUCER_UNSETTLED';end if;
  if private.closure_erasure_media_protected_v5(a,t->>'storage_path') then return null;end if;
  if exists(select 1 from storage.objects where bucket_id='profile-media' and name=t->>'storage_path') then raise exception 'ERASURE_STORAGE_NOT_CLEAN';end if;
  return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 end if;
 if r='public.app_accounts' then p:=jsonb_build_object('email','','phone','','full_name','','city','');
 elsif r='public.app_profiles' then p:=jsonb_build_object('display_name','','city','','headline','','bio','','avatar_path',null,
  'portfolio','[]'::jsonb,'skills','[]'::jsonb,'tools','[]'::jsonb,'licenses','[]'::jsonb,'vehicles','[]'::jsonb,'exclusions','[]'::jsonb,
  'years_experience',0,'radius_km',1,'available_now',false,'available_now_expires_at',null,'team_capacity',1,
  'minimum_fee_rsd',0,'rating_requester',null,'rating_worker',null,'operating_country_code',null,'profile_status','CLOSED');
 elsif r='public.needs' then p:=jsonb_build_object('title','Obrisan zadatak','description','Sadržaj uklonjen pri zatvaranju naloga.','category','OBRISANO',
  'approximate_city','','approximate_area','','approximate_lat',null,'approximate_lng',null,
  'starts_at',null,'ends_at',null,'required_skills','[]'::jsonb,'required_tools','[]'::jsonb,'required_vehicles','[]'::jsonb,'required_licenses','[]'::jsonb,
  'public_photo_paths','[]'::jsonb,'requester_price_rsd',null,'response_deadline',null,'urgent',false,
  'urgent_activated_at',null,'urgent_expires_at',null,'urgent_policy_version',null,'remaining_search_close_reason',null);
 elsif r in('private.ai_task_reviews','private.worker_ai_reviews') then p:=jsonb_build_object('envelope',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.worker_ai_sessions' then p:=jsonb_build_object('candidate',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.ai_task_review_commands' then
  foreach k in array array['evaluation_binding','evaluation','published'] loop
   if t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 elsif r='private.need_revision_events' then p:=jsonb_build_object('previous_material_snapshot',jsonb_build_object('erasedBy','AF-D22'),'new_material_snapshot',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='public.data_export_requests' then p:=jsonb_build_object('active_export_attempt_id',null,
  'export_revoked_at',coalesce(nullif(t->'export_revoked_at','null'::jsonb),to_jsonb((select requested_at from private.closure_executions_v5 where generation=g and account_id=a))));
 elsif r='private.need_publication_decisions' then p:=jsonb_build_object('public_geography_snapshot',jsonb_build_object('erasedBy','AF-D22'),'public_media_refs','[]'::jsonb,'reviewer_provenance','{}'::jsonb,'service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.preselection_qa_questions' then p:=jsonb_build_object('question_text','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r='private.preselection_qa_answer_versions' then p:=jsonb_build_object('answer_text','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r in('private.preselection_qa_policy_decisions','private.preselection_qa_materiality_decisions') then
  if exists(select 1 from private.qa_ai_commands q where q.account_id<>a and
   (case when r='private.preselection_qa_policy_decisions' then q.policy_decision_id else q.materiality_decision_id end)=(t->>'id')::uuid
   and not exists(select 1 from private.closure_executions_v5 e join private.closure_actions_v5 ac on ac.generation=e.generation
    where e.account_id=q.account_id and ac.kind='RELATIONAL_REDACT' and ac.state='VERIFIED')) then return null;end if;
  p:=jsonb_build_object('service_provenance',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.response_application_snapshots' then p:=jsonb_build_object('worker_skills','[]'::jsonb,'worker_tools','[]'::jsonb,'worker_licenses','[]'::jsonb,'worker_vehicles','[]'::jsonb);
 elsif r in('public.marketplace_responses','public.marketplace_response_versions') then
  if exists(select 1 from public.agreements x where x.selected_response_id=coalesce(t->>'response_id',t->>'id')::uuid and private.closure_erasure_agreement_protected_v5(x.id)) then return null;end if;
  p:=jsonb_build_object('scope_note','');if t?'bounded_message' then p:=p||jsonb_build_object('bounded_message','');end if;
 elsif r='public.agreement_messages' then
  -- A selected Support copy survives in its immutable scoped snapshot. The
  -- original ordinary chat row does not need the same plaintext forever.
  p:=jsonb_build_object('body','Sadržaj uklonjen pri zatvaranju naloga.','photo_asset_ids','[]'::jsonb,'voice_asset_id',null);
 elsif r='private.group_messages_v5' then p:=jsonb_build_object('body','Sadržaj uklonjen pri zatvaranju naloga.');
 elsif r in('public.agreement_versions','public.agreement_change_proposals') then
  if private.closure_erasure_agreement_protected_v5((t->>'agreement_id')::uuid) then return null;end if;
  k:=case when r='public.agreement_versions' then 'terms' else 'proposed_terms' end;
  if exists(select 1 from private.closure_scope_sources_v5 where account_id=a and generation=g and agreement_id=(t->>'agreement_id')::uuid
   and source_kind=case when r='public.agreement_versions' then 'VERSION' else 'PROPOSAL' end
   and source_id=case when r='public.agreement_versions' then t->>'version' else t->>'id' end and scope_author=a) then
   terms:=(t->k)||jsonb_build_object('scope_note','');p:=jsonb_build_object(k,terms);
  end if;
  if r='public.agreement_change_proposals' and t->>'proposed_by_account_id'=a::text then p:=p||jsonb_build_object('reason','Sadržaj uklonjen pri zatvaranju naloga.');end if;
  if p='{}'::jsonb then return null;end if;
 elsif r='public.agreement_execution' then
  -- The source problem itself is an unresolved evidence exception.
  if t->'problem_opened_at'<>'null'::jsonb then return null;end if;
  p:=jsonb_build_object('problem_narrative',null);
 elsif r='private.agreement_location_points' then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);
 elsif r='public.user_activity_events' then
  if t->>'recipient_user_id'=a::text then return jsonb_build_object('operation','DELETE','patch','{}'::jsonb);end if;
  p:=jsonb_build_object('payload',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.marketplace_audit_log' then p:=jsonb_build_object('detail',jsonb_build_object('erasedBy','AF-D22'));
 elsif r='private.retention_holds' then
  if t->'active'='true'::jsonb then return null;end if;
  p:=jsonb_build_object('hold_key','AF-D22:'||(t->>'id'));
 elsif r='private.ai_test_accounts_v5' then
  if t->'retired_at'='null'::jsonb then p:=jsonb_build_object('retired_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 elsif r='private.support_operator_grants_v5' then
  if t->'active'='true'::jsonb then p:=jsonb_build_object('active',false,'revision',(t->>'revision')::integer+1,'updated_at',(select requested_at from private.closure_executions_v5 where generation=g and account_id=a));end if;
 end if;
 -- Content-derived request hashes are no longer original-content proofs after
 -- erasure. Policy/document/source-program digests and charged units are kept.
 foreach k in array array['request_hash','input_hash','input_sha256','text_sha256','semantic_hash','content_fingerprint',
  'question_fingerprint','answer_fingerprint','context_hash','body_hash','body_sha256','completion_hash','source_hash','base_hash',
  'canonical_fingerprint','private_materiality_marker','content_hash','evaluation_result_hash','need_edit_base_fingerprint'] loop
  if t?k and jsonb_typeof(t->k)='string' then p:=p||jsonb_build_object(k,h);end if;
 end loop;
 -- These JSON command results are private source copies, not immutable legal
 -- terms. Keep identity/state columns for anti-replay, never old narrative JSON.
 if r in('private.requester_identity_commands','private.worker_ai_saves','private.need_draft_save_commands',
  'private.ai_need_turn_commands','private.worker_ai_turns','private.qa_ai_commands',
  'private.need_edit_commands','private.need_publish_commands','private.response_submit_commands','private.response_withdraw_commands',
  'private.response_revision_resolution_commands','private.remaining_search_close_commands','private.preselection_qa_commands',
  'private.account_block_commands','private.retention_jobs','private.support_commands_v5','private.support_grant_commands_v5') then
  foreach k in array array['receipt','result'] loop
   if t?k and t->k<>'null'::jsonb then p:=p||jsonb_build_object(k,jsonb_build_object('erasedBy','AF-D22'));end if;
  end loop;
 end if;
 -- An operator's note about a person is not audit metadata the subject must live with. The
 -- lineage class, its revision and its timestamps stay; the free text becomes a fixed code.
 if r in('private.account_lineage_v5','private.account_lineage_events_v5') then
  p:=p||jsonb_build_object('reason','CLOSURE_ERASED_OPERATOR_NOTE','source_ref','CLOSURE_ERASED_SOURCE_REF');
 end if;
 if r='public.needs' then p:=p||jsonb_build_object('category_id',null);end if;
 if p='{}'::jsonb or t@>p then return null;end if;
 return jsonb_build_object('operation','UPDATE','patch',p);
end $function$;

CREATE OR REPLACE FUNCTION private.data_export_dataset_catalog()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ select '[{"key": "account", "fields": ["activeMode", "city", "createdAt", "email", "fullName", "id", "phone"], "dataClass": "ACCOUNT_IDENTITY", "ownershipFilter": "t.id=REQUEST_ACCOUNT"}, {"key": "profiles", "fields": ["bio", "city", "displayName", "headline", "id", "kind", "operatingCountryCode", "skills", "status"], "dataClass": "PROFILE_DATA", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "availabilityWindows", "fields": ["endsAt", "id", "label", "profileId", "startsAt", "state"], "dataClass": "PROFILE_DATA", "ownershipFilter": "p.account_id=REQUEST_ACCOUNT"}, {"key": "availabilityRules", "fields": ["active", "endTime", "endsOn", "id", "label", "profileId", "startTime", "startsOn", "weekdays"], "dataClass": "PROFILE_DATA", "ownershipFilter": "p.account_id=REQUEST_ACCOUNT"}, {"key": "calendar", "fields": ["agreementId", "endsAt", "startsAt", "state"], "dataClass": "PROFILE_DATA", "ownershipFilter": "t.worker_account_id=REQUEST_ACCOUNT"}, {"key": "needs", "fields": ["countryCode", "description", "endsAt", "executionMode", "id", "requiredSlots", "revision", "startsAt", "status", "timezone", "title"], "dataClass": "NEED_PUBLIC", "ownershipFilter": "t.requester_account_id=REQUEST_ACCOUNT"}, {"key": "needPrivate", "fields": ["accessNotes", "exactAddress", "latitude", "longitude", "needId", "resolvedPoints"], "dataClass": "NEED_SENSITIVE", "ownershipFilter": "n.requester_account_id=REQUEST_ACCOUNT"}, {"key": "responses", "fields": ["coveredSlots", "createdAt", "id", "kind", "message", "needId", "needRevision", "priceRsd", "scopeNote", "status"], "dataClass": "RESPONSES_SELECTION", "ownershipFilter": "t.worker_account_id=REQUEST_ACCOUNT"}, {"key": "ownQuestions", "fields": ["createdAt", "id", "needId", "question", "status"], "dataClass": "PRESELECTION_QA", "ownershipFilter": "t.asker_account_id=REQUEST_ACCOUNT"}, {"key": "ownAnswers", "fields": ["answer", "createdAt", "id", "questionId", "version"], "dataClass": "PRESELECTION_QA", "ownershipFilter": "t.answered_by_account_id=REQUEST_ACCOUNT"}, {"key": "agreements", "fields": ["createdAt", "currentVersion", "id", "needId", "status"], "dataClass": "AGREEMENT_CORE", "ownershipFilter": "t.requester_account_id=REQUEST_ACCOUNT or t.worker_account_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementMessages", "fields": ["agreementId", "body", "createdAt", "id", "agreementVersion", "assetIds", "voiceAssetId"], "dataClass": "AGREEMENT_MESSAGES", "ownershipFilter": "t.sender_account_id=REQUEST_ACCOUNT and (a.requester_account_id=REQUEST_ACCOUNT or a.worker_account_id=REQUEST_ACCOUNT)"}, {"key": "consent", "fields": ["acceptedAt", "id", "privacySha256", "privacyVersion", "termsSha256", "termsVersion"], "dataClass": "LEGAL_CONSENT", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "notifications", "fields": ["body", "channel", "createdAt", "id", "readAt", "role", "state", "title"], "dataClass": "NOTIFICATION_DELIVERY", "ownershipFilter": "t.recipient_user_id=REQUEST_ACCOUNT"}, {"key": "aiMessages", "fields": ["content", "conversationId", "createdAt", "id", "role"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "mediaMetadata", "fields": ["bytesIncluded", "createdAt", "name"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.bucket_id=''profile-media'' and split_part(t.name,''/'',1)=REQUEST_ACCOUNT::text"}, {"key": "exportRequests", "fields": ["completedAt", "id", "kind", "requestedAt", "status"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownAudit", "fields": ["createdAt", "entityId", "entityType", "eventType", "id"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.actor_user_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementReviews", "fields": ["agreementId", "createdAt", "id", "rating", "tags", "comment"], "dataClass": "AGREEMENT_REVIEWS", "ownershipFilter": "t.reviewer_account_id=REQUEST_ACCOUNT and (a.requester_account_id=REQUEST_ACCOUNT or a.worker_account_id=REQUEST_ACCOUNT)"}, {"key": "ownSafetyReports", "fields": ["agreementId", "category", "createdAt", "id", "narrative", "needId", "reason", "status"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.reporter_account_id=REQUEST_ACCOUNT"}, {"key": "ownBlocks", "fields": ["active", "revision", "targetAccountId", "updatedAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.blocker_account_id=REQUEST_ACCOUNT"}, {"key": "workerAiDrafts", "fields": ["conversationId", "createdAt", "profile", "profileId", "revision", "safety"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "workerAiReviews", "fields": ["activate", "conversationId", "createdAt", "id", "profile", "revision"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "taskAiReviews", "fields": ["conversationId", "createdAt", "draftId", "draftRevision", "id", "privateFacts", "publicFacts", "responseDeadline"], "dataClass": "AI_VOLATILE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "taskAiFacts", "fields": ["conversationId", "facts", "id"], "dataClass": "AI_VOLATILE", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "workerAiTurns", "fields": ["cancelledAt", "conversationId", "createdAt", "id", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "workerAiSaves", "fields": ["createdAt", "reviewId"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "taskReviewCommands", "fields": ["createdAt", "needId", "needRevision", "reviewId", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "taskAiTurns", "fields": ["cancelledAt", "conversationId", "createdAt", "id", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "qaClassifications", "fields": ["createdAt", "id", "materiality", "needId", "needRevision", "outcome", "questionId", "state", "type"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "qaCommands", "fields": ["createdAt", "questionId", "status", "type"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT"}, {"key": "ownedMediaAssets", "fields": ["byteSize", "bytesIncluded", "conversationId", "createdAt", "height", "id", "profileId", "scope", "selected", "state", "width"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "testAdmission", "fields": ["admittedAt", "retiredAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "testAllocations", "fields": ["allocatedMaximumMicrousd", "createdAt", "kind", "measuredProviderCharge", "settledAt", "settledMicrousd", "settlementBasis"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureRequests", "fields": ["closedAt", "id", "preparedAt", "requestedAt", "revision", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureExecution", "fields": ["closedAt", "requestId", "requestedAt", "state"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "closureActions", "fields": ["dispatchedAt", "evidence", "kind", "state", "verifiedAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownGroupMessages", "fields": ["id", "groupId", "body", "createdAt"], "dataClass": "AGREEMENT_MESSAGES", "ownershipFilter": "t.sender_account_id=REQUEST_ACCOUNT"}, {"key": "ownGroupMemberships", "fields": ["groupId", "agreementId", "joinedAt", "endedAt"], "dataClass": "AGREEMENT_CORE", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownLocationSnapshots", "fields": ["agreementId", "agreementVersion", "latitude", "longitude", "accuracyMeters", "capturedAt", "sharedAt"], "dataClass": "NEED_SENSITIVE", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT and a.worker_account_id=REQUEST_ACCOUNT"}, {"key": "ownLocationCommands", "fields": ["agreementId", "agreementVersion", "kind", "state", "createdAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.actor_account_id=REQUEST_ACCOUNT and REQUEST_ACCOUNT in(a.requester_account_id,a.worker_account_id)"}, {"key": "ownAcceptedTaskMedia", "fields": ["agreementId", "agreementVersion", "needId", "needRevision", "state", "assets", "capturedAt", "bytesIncluded"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and a.requester_account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportCases", "fields": ["id", "caseNumber", "channel", "topic", "title", "desiredOutcome", "context", "status", "revision", "createdAt", "updatedAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportEvents", "fields": ["id", "caseId", "sequence", "kind", "authorRole", "body", "decisionId", "appealId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportDecisions", "fields": ["id", "caseId", "caseRevision", "outcome", "reasonCode", "explanation", "effect", "evidenceIds", "priorDecisionId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportAppeals", "fields": ["id", "caseId", "decisionId", "status", "decisionResultId", "createdAt"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportEvidence", "fields": ["id", "caseId", "eventId", "reference", "createdAt", "bytesIncluded"], "dataClass": "AUDIT_SECURITY_LOGS", "ownershipFilter": "t.submitted_by_account_id=REQUEST_ACCOUNT and c.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportCommands", "fields": ["kind", "state", "caseId", "createdAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownSupportReadMarkers", "fields": ["caseId", "sequence", "updatedAt"], "dataClass": "NOTIFICATION_DELIVERY", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementPhotos", "fields": ["id", "agreementId", "agreementVersion", "messageId", "state", "width", "height", "byteSize", "createdAt", "cancelledAt", "bytesIncluded"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownErasureSteps", "fields": ["generation", "ordinal", "state", "rowsChanged", "verifiedAt"], "dataClass": "COMMAND_LEDGERS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}, {"key": "ownAgreementVoice", "fields": ["id", "agreementId", "agreementVersion", "messageId", "state", "durationMs", "byteSize", "createdAt", "cancelledAt", "bytesIncluded"], "dataClass": "MEDIA_OBJECTS", "ownershipFilter": "t.account_id=REQUEST_ACCOUNT"}]'::jsonb || private.closure_taxonomy_export_catalog_v1() $function$;

CREATE OR REPLACE FUNCTION private.data_export_snapshot(p_account_id uuid, p_receipt_id uuid, p_binding jsonb, p_cutoff timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 with configured as (select value as config from jsonb_array_elements(p_binding#>'{delivery,datasets}')),
 owned_rows as materialized (select 'account' as key,jsonb_build_object('id',t.id,'email',t.email,'fullName',t.full_name,'city',t.city,'phone',t.phone,'activeMode',t.active_mode,'createdAt',t.created_at) as value from public.app_accounts t where t.id=p_account_id
union all
select 'profiles' as key,jsonb_build_object('id',t.id,'kind',t.kind,'displayName',t.display_name,'city',t.city,'headline',t.headline,'bio',t.bio,'status',t.profile_status,'skills',t.skills,'operatingCountryCode',t.operating_country_code) as value from public.app_profiles t where t.account_id=p_account_id
union all
select 'availabilityWindows' as key,jsonb_build_object('id',t.id,'profileId',t.profile_id,'startsAt',t.starts_at,'endsAt',t.ends_at,'state',t.availability_state,'label',t.label) as value from public.profile_availability_windows t join public.app_profiles p on p.id=t.profile_id where p.account_id=p_account_id
union all
select 'availabilityRules' as key,jsonb_build_object('id',t.id,'profileId',t.profile_id,'weekdays',t.weekdays,'startTime',t.start_time,'endTime',t.end_time,'startsOn',t.starts_on,'endsOn',t.ends_on,'active',t.active,'label',t.label) as value from public.profile_availability_rules t join public.app_profiles p on p.id=t.profile_id where p.account_id=p_account_id
union all
select 'calendar' as key,jsonb_build_object('agreementId',t.agreement_id,'startsAt',t.starts_at,'endsAt',t.ends_at,'state',t.state) as value from private.worker_calendar_events t where t.worker_account_id=p_account_id
union all
select 'needs' as key,jsonb_build_object('id',t.id,'title',t.title,'description',t.description,'status',t.status,'revision',t.revision,'countryCode',t.task_country_code,'timezone',t.task_timezone,'executionMode',t.execution_location_mode,'startsAt',t.starts_at,'endsAt',t.ends_at,'requiredSlots',t.required_slots) as value from public.needs t where t.requester_account_id=p_account_id
union all
select 'needPrivate' as key,jsonb_build_object('needId',t.need_id,'exactAddress',t.exact_address,'accessNotes',t.access_notes,'latitude',t.exact_lat,'longitude',t.exact_lng,'resolvedPoints',coalesce((select jsonb_agg(jsonb_build_object('slot',v->'slot','latitudeE6',v->'latitudeE6','longitudeE6',v->'longitudeE6','address',v->'address','accessNotes',v->'accessNotes') order by v->>'slot') from jsonb_array_elements(t.resolved_location#>'{value,points}') v),'[]'::jsonb)) as value from public.need_sensitive t join public.needs n on n.id=t.need_id where n.requester_account_id=p_account_id
union all
select 'responses' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'kind',t.response_kind,'status',t.status,'needRevision',t.submitted_against_need_revision,'priceRsd',t.price_rsd,'coveredSlots',t.covered_slots,'scopeNote',t.scope_note,'message',t.bounded_message,'createdAt',t.created_at) as value from public.marketplace_responses t where t.worker_account_id=p_account_id
union all
select 'ownQuestions' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'question',t.question_text,'status',t.status,'createdAt',t.created_at) as value from private.preselection_qa_questions t where t.asker_account_id=p_account_id
union all
select 'ownAnswers' as key,jsonb_build_object('id',t.id,'questionId',t.question_id,'version',t.answer_version,'answer',t.answer_text,'createdAt',t.created_at) as value from private.preselection_qa_answer_versions t where t.answered_by_account_id=p_account_id
union all
select 'agreements' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'status',t.status,'currentVersion',t.current_version,'createdAt',t.created_at) as value from public.agreements t where t.requester_account_id=p_account_id or t.worker_account_id=p_account_id
union all
select 'ownAgreementMessages' as key,jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'body',t.body,'createdAt',t.created_at,'agreementVersion',t.agreement_version,'assetIds',to_jsonb(t.photo_asset_ids),'voiceAssetId',t.voice_asset_id) as value from public.agreement_messages t join public.agreements a on a.id=t.agreement_id where t.sender_account_id=p_account_id and (a.requester_account_id=p_account_id or a.worker_account_id=p_account_id)
union all
select 'consent' as key,jsonb_build_object('id',t.id,'termsVersion',t.terms_version_label,'termsSha256',t.terms_content_sha256,'privacyVersion',t.privacy_version_label,'privacySha256',t.privacy_content_sha256,'acceptedAt',t.accepted_at) as value from public.account_legal_acceptance_events t where t.account_id=p_account_id
union all
select 'notifications' as key,jsonb_build_object('id',t.id,'role',t.recipient_role,'channel',t.channel,'state',t.state,'title',t.title,'body',t.body,'createdAt',t.created_at,'readAt',t.read_at) as value from public.notification_deliveries t where t.recipient_user_id=p_account_id
union all
select 'aiMessages' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'role',t.role,'content',t.body,'createdAt',t.created_at) as value from public.ai_messages t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'mediaMetadata' as key,jsonb_build_object('name',t.name,'createdAt',t.created_at,'bytesIncluded',false) as value from storage.objects t where t.bucket_id='profile-media' and split_part(t.name,'/',1)=p_account_id::text
union all
select 'exportRequests' as key,jsonb_build_object('id',t.id,'kind',t.request_kind,'status',t.status,'requestedAt',t.requested_at,'completedAt',t.completed_at) as value from public.data_export_requests t where t.account_id=p_account_id
union all
select 'ownAudit' as key,jsonb_build_object('id',t.id,'eventType',t.event_type,'entityType',t.entity_type,'entityId',t.entity_id,'createdAt',t.created_at) as value from private.marketplace_audit_log t where t.actor_user_id=p_account_id
union all
select 'ownAgreementReviews' as key,jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'rating',t.rating,'tags',t.tags,'createdAt',t.created_at,'comment',(select c.comment from private.agreement_review_comments_v1 c where c.review_id=t.id)) as value from private.agreement_reviews t join public.agreements a on a.id=t.agreement_id where t.reviewer_account_id=p_account_id and (a.requester_account_id=p_account_id or a.worker_account_id=p_account_id)
union all
select 'ownSafetyReports' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'agreementId',t.agreement_id,'category',t.category,'reason',t.reason,'narrative',t.narrative,'status',t.status,'createdAt',t.created_at) as value from private.safety_reports t where t.reporter_account_id=p_account_id
union all
select 'ownBlocks' as key,jsonb_build_object('targetAccountId',t.blocked_account_id,'active',t.active,'revision',t.revision,'updatedAt',t.updated_at) as value from private.account_blocks t where t.blocker_account_id=p_account_id
union all
select 'workerAiDrafts' as key,jsonb_build_object('conversationId',t.conversation_id,'profileId',t.profile_id,'revision',t.revision,'safety',t.safety,'profile',private.data_export_worker_candidate_v5(t.candidate),'createdAt',t.created_at) as value from private.worker_ai_sessions t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'workerAiReviews' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'revision',t.revision,'activate',private.data_export_scalar_v5(t.envelope->'activate','boolean'),'profile',private.data_export_worker_candidate_v5(t.envelope->'profile'),'createdAt',t.created_at) as value from private.worker_ai_reviews t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'taskAiReviews' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'draftId',private.data_export_scalar_v5(t.envelope->'draftId','string'),'draftRevision',private.data_export_scalar_v5(t.envelope->'draftRevision','number'),'responseDeadline',private.data_export_scalar_v5(t.envelope->'responseDeadline','string'),'publicFacts',private.data_export_task_facts_v5(t.envelope->'publicProjection'),'privateFacts',private.data_export_task_facts_v5(t.envelope->'ownerPrivateProjection'),'createdAt',t.created_at) as value from private.ai_task_reviews t join public.ai_conversations c on c.id=t.conversation_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'taskAiFacts' as key,jsonb_build_object('id',t.id,'conversationId',t.conversation_id,'facts',private.data_export_task_facts_v5(jsonb_build_array(jsonb_build_object('key',t.fact_key,'value',t.fact_value,'displayValue',t.display_value,'status',t.status)))) as value from public.ai_structured_facts t join public.ai_conversations c on c.id=t.conversation_id where c.account_id=p_account_id
union all
select 'workerAiTurns' as key,jsonb_build_object('id',t.turn_id,'conversationId',t.conversation_id,'state',t.state,'createdAt',t.created_at,'cancelledAt',t.cancelled_at) as value from private.worker_ai_turns t where t.account_id=p_account_id
union all
select 'workerAiSaves' as key,jsonb_build_object('reviewId',t.review_id,'createdAt',t.created_at) as value from private.worker_ai_saves t where t.account_id=p_account_id
union all
select 'taskReviewCommands' as key,jsonb_build_object('reviewId',t.review_id,'needId',t.need_id,'needRevision',t.need_revision,'state',t.state,'createdAt',t.created_at) as value from private.ai_task_review_commands t where t.account_id=p_account_id
union all
select 'taskAiTurns' as key,jsonb_build_object('id',t.turn_id,'conversationId',t.conversation_id,'state',t.state,'cancelledAt',t.cancelled_at,'createdAt',t.created_at) as value from private.ai_need_turn_commands t where t.account_id=p_account_id
union all
select 'qaClassifications' as key,jsonb_build_object('id',t.id,'needId',t.need_id,'needRevision',t.need_revision,'questionId',t.question_id,'type',t.command_type,'state',t.state,'outcome',t.outcome,'materiality',t.materiality,'createdAt',t.created_at) as value from private.qa_ai_commands t where t.account_id=p_account_id
union all
select 'qaCommands' as key,jsonb_build_object('type',t.command_type,'questionId',private.data_export_scalar_v5(t.result->'questionId','string'),'status',private.data_export_scalar_v5(t.result->'status','string'),'createdAt',t.created_at) as value from private.preselection_qa_commands t where t.actor_account_id=p_account_id
union all
select 'ownedMediaAssets' as key,jsonb_build_object('id',t.id,'scope',t.scope,'conversationId',t.conversation_id,'profileId',t.profile_id,'state',t.state,'selected',t.selected,'width',t.width,'height',t.height,'byteSize',t.byte_size,'bytesIncluded',false,'createdAt',t.created_at) as value from private.owned_media_assets t where t.account_id=p_account_id
union all
select 'testAdmission' as key,jsonb_build_object('admittedAt',t.admitted_at,'retiredAt',t.retired_at) as value from private.ai_test_accounts_v5 t where t.account_id=p_account_id
union all
select 'testAllocations' as key,jsonb_build_object('kind',t.kind,'allocatedMaximumMicrousd',t.max_cost_microusd,'measuredProviderCharge',coalesce(t.settlement_basis='MEASURED',false),'settledMicrousd',t.settled_microusd,'settlementBasis',t.settlement_basis,'settledAt',t.settled_at,'createdAt',t.created_at) as value from private.ai_test_reservations_v5 t where t.account_id=p_account_id
union all
select 'closureRequests' as key,jsonb_build_object('id',t.id,'state',t.state,'revision',t.revision,'requestedAt',t.requested_at,'preparedAt',t.prepared_at,'closedAt',t.closed_at) as value from private.account_closure_requests t where t.account_id=p_account_id
union all
select 'closureExecution' as key,jsonb_build_object('requestId',t.request_id,'state',t.state,'requestedAt',t.requested_at,'closedAt',t.closed_at) as value from private.closure_executions_v5 t where t.account_id=p_account_id
union all
select 'closureActions' as key,jsonb_build_object('kind',t.kind,'state',t.state,'dispatchedAt',t.dispatched_at,'verifiedAt',t.verified_at,'evidence',t.evidence) as value from private.closure_actions_v5 t where t.account_id=p_account_id
union all
select 'ownGroupMessages' as key,jsonb_build_object('id',t.id,'groupId',t.group_id,'body',t.body,'createdAt',t.created_at) as value
 from private.group_messages_v5 t where t.sender_account_id=p_account_id
union all
select 'ownGroupMemberships' as key,jsonb_build_object('groupId',t.group_id,'agreementId',t.agreement_id,'joinedAt',t.joined_at,'endedAt',t.ended_at) as value
 from private.group_memberships_v5 t where t.account_id=p_account_id
union all
select 'ownLocationSnapshots' as key,jsonb_build_object('agreementId',c.agreement_id,'agreementVersion',c.agreement_version,
 'latitude',t.latitude,'longitude',t.longitude,'accuracyMeters',t.accuracy_meters,'capturedAt',t.captured_at,'sharedAt',t.shared_at) as value
 from private.agreement_location_points t join private.agreement_location_commands c using(actor_account_id,client_request_id)
 join public.agreements a on a.id=c.agreement_id where t.actor_account_id=p_account_id and a.worker_account_id=p_account_id and c.kind='SHARE' and c.state='COMMITTED'
union all
select 'ownLocationCommands' as key,jsonb_build_object('agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'kind',t.kind,'state',t.state,'createdAt',t.created_at) as value
 from private.agreement_location_commands t join public.agreements a on a.id=t.agreement_id where t.actor_account_id=p_account_id and p_account_id in(a.requester_account_id,a.worker_account_id)
union all
select 'ownAcceptedTaskMedia' as key,jsonb_build_object('agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'needId',t.need_id,'needRevision',t.need_revision,'state',t.state,'capturedAt',t.captured_at,'bytesIncluded',false,
 'assets',(select coalesce(jsonb_agg(jsonb_build_object('assetId',x->>'assetId','width',private.data_export_scalar_v5(x->'width','number'),'height',private.data_export_scalar_v5(x->'height','number'),'byteSize',private.data_export_scalar_v5(x->'byteSize','number')) order by ordinal),'[]') from jsonb_array_elements(t.assets) with ordinality as j(x,ordinal))) as value
 from private.agreement_media_snapshots_v5 t join public.agreements a on a.id=t.agreement_id where t.account_id=p_account_id and a.requester_account_id=p_account_id
union all
select 'ownSupportCases',jsonb_build_object('id',t.id,'caseNumber',t.case_number::text,'channel',t.channel,'topic',t.topic,'title',t.title,'desiredOutcome',t.desired_outcome,'context',t.context,'status',t.status,'revision',t.revision,'createdAt',t.created_at,'updatedAt',t.updated_at) from private.support_cases_v5 t where t.account_id=p_account_id
union all
select 'ownSupportEvents',jsonb_build_object('id',t.id,'caseId',t.case_id,'sequence',t.sequence::text,'kind',t.kind,'authorRole',t.author_role,'body',case when t.kind='SAFETY_REPORT' then (select narrative from private.safety_reports where id=c.safety_report_id) else t.body end,'decisionId',t.decision_id,'appealId',t.appeal_id,'createdAt',t.created_at) from private.support_events_v5 t join private.support_cases_v5 c on c.id=t.case_id where c.account_id=p_account_id
union all
select 'ownSupportDecisions',jsonb_build_object('id',t.id,'caseId',t.case_id,'caseRevision',t.case_revision,'outcome',t.outcome,'reasonCode',t.reason_code,'explanation',t.explanation,'effect',t.effect,'evidenceIds',to_jsonb(t.evidence_ids),'priorDecisionId',t.prior_decision_id,'createdAt',t.created_at) from private.support_decisions_v5 t join private.support_cases_v5 c on c.id=t.case_id where c.account_id=p_account_id
union all
select 'ownSupportAppeals',jsonb_build_object('id',t.id,'caseId',t.case_id,'decisionId',t.decision_id,'status',t.status,'decisionResultId',t.decision_result_id,'createdAt',t.created_at) from private.support_appeals_v5 t join private.support_cases_v5 c on c.id=t.case_id where t.account_id=p_account_id and c.account_id=p_account_id
union all
select 'ownSupportEvidence',jsonb_build_object('id',t.id,'caseId',t.case_id,'eventId',t.event_id,'reference',t.snapshot,'createdAt',t.created_at,'bytesIncluded',false) from private.support_evidence_v5 t join private.support_cases_v5 c on c.id=t.case_id where t.submitted_by_account_id=p_account_id and c.account_id=p_account_id
union all
select 'ownSupportCommands',jsonb_build_object('kind',t.kind,'state',t.state,'caseId',t.case_id,'createdAt',t.created_at) from private.support_commands_v5 t where t.account_id=p_account_id
union all
select 'ownSupportReadMarkers',jsonb_build_object('caseId',t.case_id,'sequence',t.sequence::text,'updatedAt',t.updated_at) from private.support_read_markers_v5 t where t.account_id=p_account_id
union all
select 'ownAgreementPhotos',jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'messageId',t.attached_message_id,'state',t.state,
 'width',t.width,'height',t.height,'byteSize',t.byte_size,'createdAt',t.created_at,'cancelledAt',t.cancelled_at,'bytesIncluded',false) from private.agreement_photo_uploads_v5 t where t.account_id=p_account_id
union all
select 'ownAgreementVoice',jsonb_build_object('id',t.id,'agreementId',t.agreement_id,'agreementVersion',t.agreement_version,'messageId',t.attached_message_id,'state',t.state,
 'durationMs',t.duration_ms,'byteSize',t.byte_size,'createdAt',t.created_at,'cancelledAt',t.cancelled_at,'bytesIncluded',false) from private.agreement_voice_uploads_v1 t where t.account_id=p_account_id
union all
select 'ownErasureSteps',jsonb_build_object('generation',t.generation,'ordinal',t.ordinal,'state',t.state,'rowsChanged',t.affected_rows,'verifiedAt',t.verified_at) from private.closure_redaction_steps_v5 t where t.account_id=p_account_id
 union all select key,value from private.closure_taxonomy_export_rows_v1(p_account_id)),
 projected as (select r.key,(select jsonb_object_agg(field,r.value->field order by field) from jsonb_array_elements_text(c.config->'fields') field) as value
 from owned_rows r join configured c on c.config->>'key'=r.key and c.config->>'mode'='INCLUDE'),
 grouped as (select c.config->>'key' as key,coalesce(jsonb_agg(p.value order by p.value::text) filter(where p.key is not null),'[]'::jsonb) as rows
 from configured c left join projected p on p.key=c.config->>'key' where c.config->>'mode'='INCLUDE' group by c.config->>'key')
 select jsonb_build_object('schemaVersion','USKOCI_DATA_EXPORT_V2','receiptId',p_receipt_id,'accountId',p_account_id,'snapshotAt',p_cutoff,
 'projectionVersion','OWN_ACCOUNT_V5_11','policy',jsonb_build_object('policyId',p_binding->'policyId','policyVersion',p_binding->'policyVersion','privacyDocumentId',p_binding->'privacyDocumentId','privacyContentSha256',p_binding->'privacyContentSha256','sha256',p_binding->'sha256'),
 'datasets',(select jsonb_object_agg(key,rows order by key) from grouped),
 'datasetCounts',(select jsonb_object_agg(key,jsonb_array_length(rows) order by key) from grouped),
 'reviewedOmissions',(select coalesce(jsonb_agg(config order by config->>'key'),'[]'::jsonb) from configured where config->>'mode'='EXCLUDE'))::text
 where exists(select 1 from public.app_accounts where id=p_account_id);
$function$;

CREATE OR REPLACE FUNCTION private.data_export_policy_binding()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare p private.retention_policy_sets; m jsonb; d jsonb; c jsonb; seen text[]:='{}'; f jsonb; fields text[]; refs jsonb; privacy private.legal_document_versions; v_now timestamptz:=clock_timestamp();
begin
 select * into p from private.retention_policy_sets where retired_at is null and effective_at<=v_now;
 if not found then return null; end if;
 m:=p.export_delivery;
 if jsonb_typeof(m) is distinct from 'object' or m-ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets']<>'{}'::jsonb
 or not(m ?& ARRAY['schemaVersion','projectionVersion','projectionSha256','privacyDocumentId','privacyContentSha256','contentSha256','artifactLifetimeSeconds','snapshotLifetimeSeconds','downloadLifetimeSeconds','cleanupMode','snapshotCleanupMode','datasets'])
 or m->>'schemaVersion' is distinct from 'USKOCI_EXPORT_DELIVERY_V2' or m->>'projectionVersion' is distinct from 'OWN_ACCOUNT_V5_11'
 or jsonb_typeof(m->'projectionSha256') is distinct from 'string' or coalesce(m->>'projectionSha256','')!~'^[a-f0-9]{64}$'
 or m->>'projectionSha256' is distinct from private.data_export_projection_sha_v5()
 or m->>'cleanupMode' is distinct from 'DELETE_EXPORT_COPY' or m->>'snapshotCleanupMode' is distinct from 'DELETE_TEMP_SNAPSHOT'
 or coalesce(m->>'privacyDocumentId','')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or coalesce(m->>'privacyContentSha256','')!~'^[0-9a-f]{64}$' or coalesce(m->>'contentSha256','')!~'^[0-9a-f]{64}$'
 or m->>'contentSha256' is distinct from encode(extensions.digest(convert_to((m-'contentSha256')::text,'UTF8'),'sha256'),'hex') then return null; end if;
 foreach fields slice 1 in array ARRAY[ARRAY['artifactLifetimeSeconds','2592000'],ARRAY['snapshotLifetimeSeconds','2592000'],ARRAY['downloadLifetimeSeconds','900']] loop
   if jsonb_typeof(m->fields[1]) is distinct from 'number' or (m->>fields[1])!~'^[1-9][0-9]*$' or (m->>fields[1])::numeric>(fields[2])::numeric then return null; end if;
 end loop;
 if (m->>'downloadLifetimeSeconds')::integer>(m->>'artifactLifetimeSeconds')::integer then return null; end if;
 select * into privacy from private.legal_document_versions where id=(m->>'privacyDocumentId')::uuid and document_kind='PRIVACY' and is_active and retired_at is null and effective_at<=v_now and content_sha256=m->>'privacyContentSha256';
 if not found then return null; end if;
 if exists(select 1 from private.retention_data_classes dc where dc.active and dc.required and (not exists(select 1 from private.retention_policy_rules r where r.policy_id=p.id and r.data_class=dc.code) or not exists(select 1 from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'dataClass'=dc.code))) then return null; end if;
 if jsonb_typeof(m->'datasets') is distinct from 'array' or jsonb_array_length(m->'datasets')<>72 then return null; end if;
 for d in select value from jsonb_array_elements(m->'datasets') loop
   if jsonb_typeof(d) is distinct from 'object' or jsonb_typeof(d->'key') is distinct from 'string' or d->>'key'=any(seen) then return null; end if;
   select value into c from jsonb_array_elements(private.data_export_dataset_catalog()) where value->>'key'=d->>'key';
   if not found then return null; end if;seen:=array_append(seen,d->>'key');
   if d->>'mode'='EXCLUDE' then
     if d-ARRAY['key','mode','reasonCode']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','reasonCode']) or jsonb_typeof(d->'reasonCode') is distinct from 'string' or d->>'reasonCode'!~'^[A-Z][A-Z0-9_]{0,63}$' or d->>'key'='account' then return null; end if;
   elsif d->>'mode'='INCLUDE' then
     if d-ARRAY['key','mode','fields']<>'{}'::jsonb or not(d ?& ARRAY['key','mode','fields']) or jsonb_typeof(d->'fields') is distinct from 'array' then return null; end if;
     if jsonb_array_length(d->'fields')<1 or jsonb_array_length(d->'fields')>64 then return null; end if;fields:='{}';
     for f in select value from jsonb_array_elements(d->'fields') loop
       if jsonb_typeof(f)<>'string' or not((c->'fields') ? (f#>>'{}')) or f#>>'{}'=any(fields) then return null; end if; fields:=array_append(fields,f#>>'{}');
     end loop;
     if d->>'key'='account' and not('id'=any(fields)) then return null; end if;
     if d->>'key' in('mediaMetadata','ownedMediaAssets','ownAgreementPhotos','ownAgreementVoice','ownSupportEvidence') and not('bytesIncluded'=any(fields)) then return null; end if;
   else return null; end if;
 end loop;
 select coalesce(jsonb_agg(to_jsonb(r) order by data_class),'[]'::jsonb) into refs from private.retention_policy_rules r where policy_id=p.id;
 return jsonb_build_object('policyId',p.id,'policyVersion',p.policy_version,'privacyDocumentId',privacy.id,'privacyContentSha256',privacy.content_sha256,'delivery',m,
 'sha256',encode(extensions.digest(convert_to(jsonb_build_object('policy',to_jsonb(p),'rules',refs,'privacy',to_jsonb(privacy),'catalog',private.data_export_dataset_catalog())::text,'UTF8'),'sha256'),'hex'));
exception when data_exception then return null;
end $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_prepare_admission_service(p_owner_account_id uuid, p_request_key uuid, p_purpose text, p_source_review_id uuid, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v_review_digest text;v_expiry timestamptz;v_version bigint;
 v_review_plan jsonb;v_expected_review_digest text;
 v_plan_digest text;v_id uuid;v_existing private.work_taxonomy_admissions_v1%ROWTYPE;
 v_action text;v_mode text;v_parent uuid;v_category uuid;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF p_owner_account_id IS NULL OR p_request_key IS NULL OR p_source_review_id IS NULL
 OR p_plan IS NULL OR jsonb_typeof(p_plan)<>'object'
 OR p_purpose NOT IN ('WORKER_CAPABILITY','NEED_SERVICE') THEN
  RAISE EXCEPTION 'ADMISSION_INPUT_INVALID' USING errcode='22023'; END IF;
 IF pg_column_size(p_plan)>12000 THEN RAISE EXCEPTION 'ADMISSION_PLAN_TOO_LARGE' USING errcode='22023'; END IF;
 v_action:=p_plan->>'action';v_mode:=p_plan->>'mode';
 IF v_action NOT IN ('REUSE_EXISTING','CREATE_CHILD') OR v_mode NOT IN ('ON_SITE','REMOTE')
 OR jsonb_typeof(p_plan->'catalogVersion')<>'number'
 OR jsonb_typeof(p_plan->'reason')<>'string'
 OR char_length(btrim(p_plan->>'reason')) NOT BETWEEN 10 AND 1000
 THEN RAISE EXCEPTION 'ADMISSION_PLAN_REVIEW_REQUIRED' USING errcode='22023'; END IF;
 IF p_purpose='WORKER_CAPABILITY' THEN
  SELECT w.envelope->>'displayedContentDigest',w.expires_at,
         w.envelope->'classificationProposal',
         encode(extensions.digest(
          ((w.envelope - 'displayedContentDigest') ||
           jsonb_build_object('baseHash',w.base_hash))::text,'sha256'),'hex')
    INTO v_review_digest,v_expiry,v_review_plan,v_expected_review_digest
  FROM private.worker_ai_reviews w
  WHERE w.id=p_source_review_id AND w.account_id=p_owner_account_id
    AND (w.envelope->>'canAccept')::boolean IS TRUE AND w.expires_at>statement_timestamp();
 ELSE
  SELECT t.envelope->>'displayedContentDigest',t.expires_at,
         t.envelope->'classificationProposal',
         encode(extensions.digest(
            jsonb_build_object('envelope',t.envelope - 'displayedContentDigest',
                               'policy',t.policy_binding)::text,'sha256'),'hex')
    INTO v_review_digest,v_expiry,v_review_plan,v_expected_review_digest
  FROM private.ai_task_reviews t
  WHERE t.id=p_source_review_id AND t.account_id=p_owner_account_id
    AND (t.envelope->>'canAccept')::boolean IS TRUE AND t.expires_at>statement_timestamp();
 END IF;
 -- Fail closed for legacy reviews: the classification must be part of the
 -- SAME server-owned payload that the owner actually reviewed.
 IF v_review_digest IS NULL OR v_review_digest !~ '^[0-9a-f]{64}$'
    OR v_review_plan IS NULL OR v_review_plan IS DISTINCT FROM p_plan
    OR v_review_digest IS DISTINCT FROM v_expected_review_digest THEN
  RAISE EXCEPTION 'ADMISSION_REVIEW_PLAN_NOT_DISPLAYED' USING errcode='42501';
 END IF;
 SELECT catalog_version INTO v_version FROM private.work_taxonomy_control WHERE singleton;
 IF v_version IS NULL OR (p_plan->>'catalogVersion')::bigint <> v_version THEN
  RAISE EXCEPTION 'ADMISSION_STALE_CATALOG' USING errcode='40001'; END IF;
 IF v_action='REUSE_EXISTING' THEN
   IF (p_plan->>'categoryId') IS NULL THEN RAISE EXCEPTION 'ADMISSION_ID_REQUIRED'; END IF;
   v_category:=(p_plan->>'categoryId')::uuid;
   PERFORM 1 FROM private.work_taxonomy_categories c
    JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
    WHERE c.id=v_category AND c.state='ESTABLISHED' AND m.execution_scope=v_mode;
   IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_UNKNOWN_CATEGORY_OR_MODE'; END IF;
 ELSE
   IF jsonb_typeof(p_plan->'path')<>'array'
      OR jsonb_array_length(p_plan->'path') NOT BETWEEN 1 AND 6
      OR (p_plan->>'parentId') IS NULL THEN
    RAISE EXCEPTION 'ADMISSION_PATH_INVALID' USING errcode='22023'; END IF;
   v_parent:=(p_plan->>'parentId')::uuid;
   PERFORM 1 FROM private.work_taxonomy_categories c
     JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
     WHERE c.id=v_parent AND c.state='ESTABLISHED' AND m.execution_scope=v_mode;
   IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_UNKNOWN_PARENT_OR_MODE'; END IF;
   -- New root or subtree restructure always requires a separate operator gate.
   IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_plan->'path') t(label)
      WHERE char_length(btrim(t.label)) NOT BETWEEN 3 AND 120
        OR btrim(t.label) ~ '[<>{}\\]' OR btrim(t.label) ~ '[[:cntrl:]]')
     THEN RAISE EXCEPTION 'ADMISSION_NODE_INVALID' USING errcode='22023'; END IF;
   -- Every new level is screened; a safe leaf cannot hide an unsafe ancestor.
   IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_plan->'path') t(label)
      WHERE private.taxonomy_risk_triage_v1(t.label) IN ('BLOCKED','REVIEW_REQUIRED'))
     THEN RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
   -- Server risk triage is a risk gate, NOT a semantic classifier.
   IF private.taxonomy_risk_triage_v1(p_plan->'path'->>(jsonb_array_length(p_plan->'path')-1))
      <> 'LOW_RISK_CANDIDATE'
     THEN RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
 END IF;
 v_plan_digest:=encode(extensions.digest(convert_to(p_plan::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO v_existing FROM private.work_taxonomy_admissions_v1
 WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key;
 IF FOUND THEN
  IF v_existing.plan_digest<>v_plan_digest OR v_existing.source_review_id<>p_source_review_id
      OR v_existing.purpose<>p_purpose THEN
   RAISE EXCEPTION 'ADMISSION_REQUEST_REUSED' USING errcode='22023'; END IF;
  RETURN jsonb_build_object('admissionId',v_existing.id,'planDigest',v_existing.plan_digest,
    'status',v_existing.status,'catalogVersion',v_existing.catalog_version);
 END IF;
 INSERT INTO private.work_taxonomy_admissions_v1
 (owner_account_id,request_key,purpose,source_review_id,source_review_digest,plan,
  plan_digest,catalog_version,catalog_fingerprint,expires_at)
 VALUES(p_owner_account_id,p_request_key,p_purpose,p_source_review_id,v_review_digest,p_plan,
 v_plan_digest,v_version,private.taxonomy_admission_fingerprint_v1(),
 least(v_expiry,statement_timestamp()+interval '30 minutes'))
 RETURNING id INTO v_id;
 RETURN jsonb_build_object('admissionId',v_id,'planDigest',v_plan_digest,
  'status','PENDING','catalogVersion',v_version);
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_commit_reviewed_batch_service(p_owner_account_id uuid, p_request_key uuid, p_purpose text, p_source_review_id uuid, p_plans jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_id uuid;v_old private.work_taxonomy_review_batches_v1%ROWTYPE;
 v_review jsonb;v_review_digest text;v_computed_digest text;
 v_expiry timestamptz;v_saved_at timestamptz;v_review_fingerprint text;
 v_version bigint;v_review_version bigint;v_fingerprint text;v_plans_digest text;
 v_plan jsonb;v_service text;v_mode text;v_action text;
 v_parent uuid;v_category uuid;v_canonical uuid;v_current_parent uuid;
 v_label text;v_key text;v_ref text;v_count integer;v_created integer:=0;
 v_index integer;v_step integer;v_duplicate text;
 v_seen_services text[]:=ARRAY[]::text[];
 v_seen_targets text[]:=ARRAY[]::text[];
 v_bound boolean;v_visible_mode boolean;v_found boolean;
 v_items jsonb:='[]'::jsonb;v_result jsonb;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF p_owner_account_id IS NULL OR p_request_key IS NULL OR p_source_review_id IS NULL
    OR p_purpose NOT IN ('WORKER_CAPABILITY','NEED_SERVICE')
    OR jsonb_typeof(p_plans)<>'array'
    OR (p_purpose='WORKER_CAPABILITY' AND jsonb_array_length(p_plans) NOT BETWEEN 1 AND 24)
    OR (p_purpose='NEED_SERVICE' AND jsonb_array_length(p_plans)<>1)
    OR pg_column_size(p_plans)>16000
 THEN RAISE EXCEPTION 'BATCH_INPUT_INVALID' USING errcode='22023'; END IF;
 v_plans_digest:=encode(extensions.digest(convert_to(p_plans::text,'UTF8'),'sha256'),'hex');

 -- A replay returns its ORIGINAL receipt even if later unrelated catalog writes
 -- changed the control version. Reuse of a key for another user review fails.
 SELECT * INTO v_old FROM private.work_taxonomy_review_batches_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key FOR UPDATE;
 IF FOUND THEN
  IF v_old.purpose<>p_purpose OR v_old.source_review_id<>p_source_review_id
    OR v_old.plans_digest<>v_plans_digest OR v_old.plans IS DISTINCT FROM p_plans
  THEN RAISE EXCEPTION 'BATCH_REQUEST_KEY_REUSED' USING errcode='22023'; END IF;
  RETURN v_old.result;
 END IF;

 IF p_purpose='WORKER_CAPABILITY' THEN
  SELECT w.envelope,w.envelope->>'displayedContentDigest',w.expires_at,
   encode(extensions.digest(((w.envelope-'displayedContentDigest')
     ||jsonb_build_object('baseHash',w.base_hash))::text,'sha256'),'hex')
    INTO v_review,v_review_digest,v_expiry,v_computed_digest
   FROM private.worker_ai_reviews w
   WHERE w.id=p_source_review_id AND w.account_id=p_owner_account_id FOR SHARE;
  SELECT min(s.created_at) INTO v_saved_at FROM private.worker_ai_saves s
    WHERE s.review_id=p_source_review_id AND s.account_id=p_owner_account_id
      AND s.client_request_id=p_request_key;
  v_bound:=v_saved_at IS NOT NULL;
 ELSE
  SELECT t.envelope,t.envelope->>'displayedContentDigest',t.expires_at,
   encode(extensions.digest(jsonb_build_object('envelope',
     t.envelope-'displayedContentDigest','policy',t.policy_binding)::text,'sha256'),'hex')
    INTO v_review,v_review_digest,v_expiry,v_computed_digest
   FROM private.ai_task_reviews t
   WHERE t.id=p_source_review_id AND t.account_id=p_owner_account_id FOR SHARE;
  SELECT min(c.created_at) INTO v_saved_at FROM private.ai_task_review_commands c
    WHERE c.review_id=p_source_review_id AND c.account_id=p_owner_account_id
      AND c.client_request_id=p_request_key
      AND c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED');
  v_bound:=v_saved_at IS NOT NULL;
 END IF;
 IF NOT coalesce(v_bound,false) THEN
  RAISE EXCEPTION 'BATCH_EXISTING_USER_SAVE_REQUIRED' USING errcode='42501'; END IF;
 -- Approval must have happened WHILE the review was valid.
 -- Outbox retries may run later; expiring the review AFTER a successful human
 -- Save/Accept must not silently discard a confirmed service.
 IF v_review IS NULL OR v_review->'canAccept' IS DISTINCT FROM 'true'::jsonb
    OR v_saved_at>v_expiry OR v_review_digest IS NULL
    OR v_review_digest !~ '^[0-9a-f]{64}$'
    OR v_computed_digest IS DISTINCT FROM v_review_digest
    OR v_review->'classificationCandidates' IS DISTINCT FROM p_plans
 THEN RAISE EXCEPTION 'BATCH_REVIEW_NOT_BOUND' USING errcode='42501'; END IF;
 v_review_fingerprint:=v_review->>'classificationCatalogFingerprint';
 IF v_review_fingerprint IS NULL OR
    v_review_fingerprint !~ '^[0-9a-f]{32}$' THEN
   RAISE EXCEPTION 'BATCH_CATALOG_FINGERPRINT_REQUIRED' USING errcode='42501'; END IF;

 -- Single serialized admission pass: intermediate catalog bumps do NOT make
 -- later items in the SAME reviewed batch stale.
 SELECT catalog_version INTO v_version FROM private.work_taxonomy_control
  WHERE singleton FOR UPDATE;
 IF v_version IS NULL THEN RAISE EXCEPTION 'BATCH_CATALOG_MISSING'; END IF;
 v_review_version:=v_version;
 v_fingerprint:=private.taxonomy_admission_fingerprint_v1();
 IF v_fingerprint<>v_review_fingerprint THEN
  RAISE EXCEPTION 'BATCH_STALE_CATALOG' USING errcode='40001'; END IF;
 FOR v_index IN 0..jsonb_array_length(p_plans)-1 LOOP
  v_plan:=p_plans->v_index;
  IF jsonb_typeof(v_plan)<>'object'
     OR v_plan ?& array['action','service','mode','catalogVersion','reason'] IS NOT TRUE
     OR jsonb_typeof(v_plan->'catalogVersion')<>'number'
     OR (v_plan->>'catalogVersion')::bigint<> (v_review->>'classificationCatalogVersion')::bigint
     OR (v_plan->>'catalogVersion')::bigint<>v_review_version
     OR jsonb_typeof(v_plan->'reason')<>'string'
     OR char_length(btrim(v_plan->>'reason')) NOT BETWEEN 10 AND 1000
  THEN RAISE EXCEPTION 'BATCH_INVALID_OR_STALE_PLAN' USING errcode='22023'; END IF;
  v_service:=btrim(v_plan->>'service');
  v_mode:=v_plan->>'mode';
  v_action:=v_plan->>'action';
  IF char_length(v_service) NOT BETWEEN 3 AND 120 OR
     v_mode NOT IN ('ON_SITE','REMOTE') OR
     v_action NOT IN ('REUSE_EXISTING','CREATE_CHILD','CREATE_NEW_BRANCH')
  THEN RAISE EXCEPTION 'BATCH_SCOPE_OR_SERVICE_INVALID' USING errcode='22023'; END IF;
  v_key:=private.taxonomy_normalize_v1(v_service);
  v_duplicate:=v_key||'|'||v_mode;
  IF v_duplicate=ANY(v_seen_services) THEN
   RAISE EXCEPTION 'BATCH_DUPLICATE_SERVICE' USING errcode='22023'; END IF;
  v_seen_services:=array_append(v_seen_services,v_duplicate);

  -- Require the service to be a HUMAN-REVIEWED meaning in the existing
  -- profile/need content. A model may not add undeclared worker skills.
  IF p_purpose='WORKER_CAPABILITY' THEN
    v_found:=EXISTS(SELECT 1 FROM jsonb_array_elements_text(
       coalesce(v_review#>'{profile,skills}','[]'::jsonb)) x(service)
       WHERE private.taxonomy_normalize_v1(x.service)=v_key);
    v_visible_mode:=EXISTS(SELECT 1 FROM jsonb_array_elements(
      coalesce(v_review->'reviewedServiceModes','[]'::jsonb)) x(item)
       WHERE private.taxonomy_normalize_v1(x.item->>'service')=v_key
         AND x.item->>'mode'=v_mode);
  ELSE
    v_found:=EXISTS(SELECT 1 FROM jsonb_array_elements(
       coalesce(v_review->'publicProjection','[]'::jsonb)) x(fact)
       WHERE x.fact->>'key'='need.category'
         AND private.taxonomy_normalize_v1(x.fact->>'value')=v_key);
    v_visible_mode:=(CASE v_review#>>'{location,geography,mode}'
      WHEN 'REMOTE' THEN 'REMOTE'
      WHEN 'STATIONARY' THEN 'ON_SITE'
      WHEN 'POINT_TO_POINT' THEN 'ON_SITE'
      WHEN 'AREA_BASED' THEN 'ON_SITE'
      ELSE 'UNCONFIRMED' END)=v_mode;
  END IF;
  IF NOT coalesce(v_found,false) OR NOT coalesce(v_visible_mode,false)
   THEN RAISE EXCEPTION 'BATCH_SERVICE_OR_MODE_NOT_REVIEWED' USING errcode='42501'; END IF;

  IF v_action='REUSE_EXISTING' THEN
   IF (v_plan->>'categoryId') IS NULL OR
      v_plan ? 'parentId' OR v_plan ? 'path' THEN
    RAISE EXCEPTION 'BATCH_REUSE_STRUCTURE_INVALID' USING errcode='22023'; END IF;
   v_category:=(v_plan->>'categoryId')::uuid;
   PERFORM 1 FROM private.work_taxonomy_categories c
    JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
    WHERE c.id=v_category AND c.state='ESTABLISHED'
      AND m.execution_scope=v_mode;
   IF NOT FOUND THEN RAISE EXCEPTION 'BATCH_CATEGORY_OR_MODE_MISSING' USING errcode='22023'; END IF;
   -- A model-provided existing ID cannot change the actual meaning of
   -- a human-reviewed service. Only a canonical name or STORED alias qualifies.
   IF NOT EXISTS (
     SELECT 1 FROM private.work_taxonomy_categories c
     WHERE c.id=v_category AND c.state='ESTABLISHED'
       AND (c.canonical_key=v_key OR EXISTS (
         SELECT 1 FROM private.work_taxonomy_aliases a
         WHERE a.category_id=c.id AND a.normalized_key=v_key))
   ) THEN
     RAISE EXCEPTION 'BATCH_SEMANTIC_IDENTITY_MISMATCH' USING errcode='42501';
   END IF;
  ELSE
   IF v_plan ? 'categoryId' OR jsonb_typeof(v_plan->'path')<>'array'
      OR jsonb_array_length(v_plan->'path') NOT BETWEEN 1 AND 6
      OR (v_action='CREATE_CHILD' AND (v_plan->>'parentId') IS NULL)
      OR (v_action='CREATE_NEW_BRANCH' AND
          (v_plan->'parentId' IS DISTINCT FROM 'null'::jsonb
           OR v_plan->'parentLabel' IS DISTINCT FROM 'null'::jsonb)) THEN
    RAISE EXCEPTION 'BATCH_CHILD_STRUCTURE_INVALID' USING errcode='22023'; END IF;
   -- A newly created leaf must be exactly the reviewed human service meaning.
   IF private.taxonomy_normalize_v1(v_plan->'path'->>(jsonb_array_length(v_plan->'path')-1))
       <>private.taxonomy_normalize_v1(v_service) THEN
      RAISE EXCEPTION 'BATCH_SERVICE_LEAF_MISMATCH' USING errcode='42501'; END IF;
   IF v_action='CREATE_CHILD' THEN
     v_parent:=(v_plan->>'parentId')::uuid;
     PERFORM 1 FROM private.work_taxonomy_categories c
      JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
      WHERE c.id=v_parent AND c.state='ESTABLISHED'
        AND m.execution_scope=v_mode;
     IF NOT FOUND THEN RAISE EXCEPTION 'BATCH_PARENT_OR_MODE_MISSING' USING errcode='22023'; END IF;
   ELSE
     v_parent:=NULL;
   END IF;
   FOR v_step IN 0..jsonb_array_length(v_plan->'path')-1 LOOP
    v_label:=btrim(v_plan->'path'->>v_step);
    IF char_length(v_label) NOT BETWEEN 3 AND 120 OR
       v_label ~ '[<>{}\\]' OR v_label ~ '[[:cntrl:]]' OR
       private.taxonomy_risk_triage_v1(v_label) IN ('BLOCKED','REVIEW_REQUIRED')
    THEN RAISE EXCEPTION 'BATCH_UNSAFE_CATEGORY' USING errcode='42501'; END IF;
    IF v_step=jsonb_array_length(v_plan->'path')-1 AND
       private.taxonomy_risk_triage_v1(v_label)<>'LOW_RISK_CANDIDATE'
    THEN RAISE EXCEPTION 'BATCH_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
    v_key:=private.taxonomy_normalize_v1(v_label);
    IF char_length(v_key) NOT BETWEEN 3 AND 160 OR
       EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a
          WHERE a.normalized_key=v_key)
    THEN RAISE EXCEPTION 'BATCH_ALIAS_OR_KEY_COLLISION' USING errcode='22023'; END IF;
    v_category:=NULL;v_current_parent:=NULL;
    SELECT c.id,c.parent_id INTO v_category,v_current_parent
      FROM private.work_taxonomy_categories c WHERE c.canonical_key=v_key
      FOR UPDATE;
    IF FOUND THEN
     IF v_current_parent IS DISTINCT FROM v_parent OR NOT EXISTS(
       SELECT 1 FROM private.work_taxonomy_category_modes
       WHERE category_id=v_category AND execution_scope=v_mode)
     THEN RAISE EXCEPTION 'BATCH_SEMANTIC_OR_MODE_COLLISION' USING errcode='22023'; END IF;
    ELSE
     UPDATE private.work_taxonomy_control
      SET catalog_version=catalog_version+1,updated_at=statement_timestamp()
      WHERE singleton RETURNING catalog_version INTO v_version;
     INSERT INTO private.work_taxonomy_categories
       (canonical_key,label,parent_id,state,source,catalog_version)
     VALUES(v_key,v_label,v_parent,'ESTABLISHED','AI_REVIEWED',v_version)
      RETURNING id INTO v_category;
     INSERT INTO private.work_taxonomy_category_modes(category_id,execution_scope,source_ref)
      VALUES(v_category,v_mode,'REVIEWED_BATCH_V1');
     INSERT INTO private.work_taxonomy_audit
      (action,category_id,normalized_key,catalog_version,source_ref)
      VALUES('AUTO_CREATED',v_category,v_key,v_version,
        'REVIEWED_BATCH_V1:'||p_request_key::text);
     v_created:=v_created+1;
    END IF;
    v_parent:=v_category;
   END LOOP;
  END IF;
  v_ref:=v_category::text||'|'||v_mode;
  IF v_ref=ANY(v_seen_targets) THEN
    RAISE EXCEPTION 'BATCH_DUPLICATE_CANONICAL_ID' USING errcode='22023'; END IF;
  v_seen_targets:=array_append(v_seen_targets,v_ref);
  v_items:=v_items||jsonb_build_array(jsonb_build_object(
    'service',v_service,'mode',v_mode,'categoryId',v_category));
 END LOOP;
 -- All category changes and ONE receipt share the same DB transaction.
 v_result:=jsonb_build_object('status','COMMITTED','items',v_items,
  'createdCount',v_created,'catalogVersion',v_version,
  'capabilityAuthority','NONE','needRevisionAuthority','NONE',
  'notificationAuthority','NONE','requiresBinding',true);
 INSERT INTO private.work_taxonomy_review_batches_v1
 (owner_account_id,request_key,purpose,source_review_id,review_digest,
  plans_digest,plans,catalog_version,result)
 VALUES(p_owner_account_id,p_request_key,p_purpose,p_source_review_id,
  v_review_digest,v_plans_digest,p_plans,v_version,v_result);
 RETURN v_result;
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_bind_reviewed_worker_service(p_owner_account_id uuid, p_request_key uuid, p_source_review_id uuid, p_profile_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_existing private.work_taxonomy_worker_bindings_v1%ROWTYPE;
 v_batch private.work_taxonomy_review_batches_v1%ROWTYPE;
 v_review private.worker_ai_reviews%ROWTYPE;
 v_save private.worker_ai_saves%ROWTYPE;
 v_profile public.app_profiles%ROWTYPE;
 v_digest text;v_item jsonb;v_plan jsonb;v_category uuid;
 v_key text;v_mode text;v_seen text[]:=ARRAY[]::text[];
 v_modes text[]:=ARRAY[]::text[];v_onsite boolean:=false;v_remote boolean:=false;
 v_result jsonb;v_count integer:=0;v_skills jsonb;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN
  RAISE EXCEPTION 'WORKER_BINDER_SERVICE_ROLE_REQUIRED' USING errcode='42501';
 END IF;
 IF p_owner_account_id IS NULL OR p_request_key IS NULL
   OR p_source_review_id IS NULL OR p_profile_id IS NULL THEN
  RAISE EXCEPTION 'WORKER_BINDER_INPUT_INVALID' USING errcode='22023';
 END IF;
 -- Replays are read-only and bound to the very same worker/review/request.
 SELECT * INTO v_existing FROM private.work_taxonomy_worker_bindings_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key FOR UPDATE;
 IF FOUND THEN
  IF v_existing.source_review_id<>p_source_review_id OR v_existing.profile_id<>p_profile_id
  THEN RAISE EXCEPTION 'WORKER_BINDER_REQUEST_KEY_REUSED' USING errcode='22023'; END IF;
  RETURN v_existing.result;
 END IF;
 SELECT * INTO v_batch FROM private.work_taxonomy_review_batches_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key
   AND source_review_id=p_source_review_id AND purpose='WORKER_CAPABILITY'
  FOR SHARE;
 IF NOT FOUND OR v_batch.result->>'status'<>'COMMITTED'
   OR v_batch.result->'requiresBinding' IS DISTINCT FROM 'true'::jsonb
   OR v_batch.result->'capabilityAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR v_batch.result->'notificationAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR jsonb_typeof(v_batch.plans)<>'array'
   OR jsonb_typeof(v_batch.result->'items')<>'array'
   OR jsonb_array_length(v_batch.plans) NOT BETWEEN 1 AND 24
   OR jsonb_array_length(v_batch.result->'items')<>jsonb_array_length(v_batch.plans)
 THEN RAISE EXCEPTION 'WORKER_BINDER_ADMISSION_NOT_COMMITTED' USING errcode='42501'; END IF;
 SELECT * INTO v_review FROM private.worker_ai_reviews
  WHERE id=p_source_review_id AND account_id=p_owner_account_id FOR SHARE;
 IF NOT FOUND OR v_review.envelope->>'classificationState'<>'READY'
   OR v_review.envelope->>'displayedContentDigest' IS DISTINCT FROM v_batch.review_digest
   OR v_review.envelope->'classificationCandidates' IS DISTINCT FROM v_batch.plans
   OR v_review.envelope->'canAccept' IS DISTINCT FROM 'true'::jsonb
   OR jsonb_typeof(v_review.envelope->'reviewedServiceModes')<>'array'
   OR jsonb_array_length(v_review.envelope->'reviewedServiceModes')
       <>jsonb_array_length(v_batch.plans)
   OR v_review.envelope->>'profileId' IS DISTINCT FROM p_profile_id::text
 THEN RAISE EXCEPTION 'WORKER_BINDER_REVIEW_NOT_BOUND' USING errcode='42501'; END IF;
 v_digest:=encode(extensions.digest(
  ((v_review.envelope-'displayedContentDigest')
    ||jsonb_build_object('baseHash',v_review.base_hash))::text,'sha256'),'hex');
 IF v_digest IS DISTINCT FROM v_batch.review_digest THEN
   RAISE EXCEPTION 'WORKER_BINDER_REVIEW_DIGEST_INVALID' USING errcode='42501'; END IF;
 SELECT * INTO v_save FROM private.worker_ai_saves
  WHERE review_id=p_source_review_id AND account_id=p_owner_account_id
    AND client_request_id=p_request_key FOR SHARE;
 IF NOT FOUND OR v_save.created_at>v_review.expires_at
   OR v_save.receipt->'saved' IS DISTINCT FROM 'true'::jsonb
   OR v_save.receipt->>'profileId' IS DISTINCT FROM p_profile_id::text
   OR v_save.receipt->>'profileStatus'<>'ACTIVE'
 THEN RAISE EXCEPTION 'WORKER_BINDER_SAVE_OR_ACTIVATION_REQUIRED' USING errcode='42501'; END IF;
 -- A delayed outbox command from an OLD Save must never re-enable modes
 -- superseded by a newer user-confirmed worker review for this same profile.
 IF EXISTS(SELECT 1 FROM private.worker_ai_saves newer
   WHERE newer.account_id=p_owner_account_id
     AND newer.created_at>v_save.created_at
     AND newer.receipt->>'profileId'=p_profile_id::text)
 THEN RAISE EXCEPTION 'WORKER_BINDER_NEWER_SAVE_EXISTS' USING errcode='PT409'; END IF;
 -- Hold current worker profile throughout the transaction. Reject any edit
 -- after the reviewed Save, even if the new skill text happens to be identical.
 SELECT * INTO v_profile FROM public.app_profiles
  WHERE id=p_profile_id AND account_id=p_owner_account_id AND kind='WORKER'
  FOR UPDATE;
 v_skills:=v_review.envelope#>'{profile,skills}';
 IF NOT FOUND OR v_profile.profile_status<>'ACTIVE'
   OR v_profile.updated_at>v_save.created_at
   OR jsonb_typeof(v_skills)<>'array'
   OR to_jsonb(v_profile.skills) IS DISTINCT FROM v_skills
 THEN RAISE EXCEPTION 'WORKER_BINDER_CURRENT_PROFILE_REQUIRED' USING errcode='PT409'; END IF;
 -- Make every scope and category EXACT. A related branch never certifies ability.
 FOR v_count IN 0..jsonb_array_length(v_batch.plans)-1 LOOP
   v_plan:=v_batch.plans->v_count;
   v_item:=v_batch.result->'items'->v_count;
   v_key:=private.taxonomy_normalize_v1(v_item->>'service');
   v_mode:=v_item->>'mode';
   IF v_plan->>'mode' IS DISTINCT FROM v_mode
     OR private.taxonomy_normalize_v1(v_plan->>'service') IS DISTINCT FROM v_key
     OR v_plan->>'action' NOT IN ('REUSE_EXISTING','CREATE_CHILD','CREATE_NEW_BRANCH')
     OR v_mode NOT IN ('ON_SITE','REMOTE')
     OR jsonb_typeof(v_item->'categoryId')<>'string'
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_skills) offered(value)
       WHERE private.taxonomy_normalize_v1(offered.value#>>'{}')=v_key)
     OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(
        v_review.envelope->'reviewedServiceModes') m(value)
       WHERE private.taxonomy_normalize_v1(m.value->>'service')=v_key
         AND m.value->>'mode'=v_mode)
     OR v_key||'|'||v_mode=ANY(v_seen)
   THEN RAISE EXCEPTION 'WORKER_BINDER_SERVICE_OR_MODE_NOT_REVIEWED' USING errcode='42501'; END IF;
   v_seen:=array_append(v_seen,v_key||'|'||v_mode);
   v_category:=(v_item->>'categoryId')::uuid;
   IF NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories c
      JOIN private.work_taxonomy_category_modes cm ON cm.category_id=c.id
      WHERE c.id=v_category AND c.state='ESTABLISHED'
        AND cm.execution_scope=v_mode
        AND (c.canonical_key=v_key OR EXISTS(
          SELECT 1 FROM private.work_taxonomy_aliases a
          WHERE a.category_id=c.id AND a.normalized_key=v_key)))
   THEN RAISE EXCEPTION 'WORKER_BINDER_CATEGORY_STALE' USING errcode='42501'; END IF;
   -- A past withdrawal (excluded=true) is NOT permanent: the owner may
   -- deliberately offer this service again in a NEW signed Save. ONLY this
   -- binder may restore it, with zero inherited related-offer consent.
   IF v_mode='ON_SITE' THEN v_onsite:=true; ELSE v_remote:=true; END IF;
 END LOOP;
 -- A recent explicit global-mode change must not be overwritten by a delayed
 -- binder from an older review. All updates below are ONE DB transaction.
 IF EXISTS(SELECT 1 FROM private.worker_execution_mode_choices choice
   WHERE choice.worker_profile_id=p_profile_id AND choice.updated_at>v_save.created_at)
 THEN RAISE EXCEPTION 'WORKER_BINDER_NEWER_GLOBAL_MODE' USING errcode='PT409'; END IF;
 IF v_onsite THEN v_modes:=array_append(v_modes,'ON_SITE'); END IF;
 IF v_remote THEN v_modes:=array_append(v_modes,'REMOTE'); END IF;
 INSERT INTO private.worker_execution_mode_choices(
   worker_profile_id,worker_account_id,modes,consent_source,confirmed_at,updated_at)
 VALUES(p_profile_id,p_owner_account_id,v_modes,'EXPLICIT_PROFILE_REVIEW',
   statement_timestamp(),statement_timestamp())
 ON CONFLICT(worker_profile_id) DO UPDATE
   SET modes=excluded.modes,consent_source='EXPLICIT_PROFILE_REVIEW',
       confirmed_at=statement_timestamp(),updated_at=statement_timestamp();
 -- Catalog identities and per-service scope are granted only AFTER the
 -- signed review, saved receipt and current profile all passed.
 FOR v_count IN 0..jsonb_array_length(v_batch.plans)-1 LOOP
   v_item:=v_batch.result->'items'->v_count;
   v_category:=(v_item->>'categoryId')::uuid;v_mode:=v_item->>'mode';
   INSERT INTO private.work_taxonomy_worker_capabilities(
      worker_account_id,category_id,confirmed_at,allow_related_offers,excluded,origin)
   VALUES(p_owner_account_id,v_category,statement_timestamp(),false,false,'WORKER_CONFIRMED')
   ON CONFLICT(worker_account_id,category_id) DO UPDATE
     SET confirmed_at=statement_timestamp(),updated_at=statement_timestamp(),
         excluded=false,allow_related_offers=false,origin='WORKER_CONFIRMED';
   INSERT INTO private.taxonomy_confirmed_worker_modes_v1(
     worker_account_id,category_id,execution_scope,source_review_id,source_request_key,
     confirmed_at,active)
   VALUES(p_owner_account_id,v_category,v_mode,p_source_review_id,p_request_key,
     statement_timestamp(),true)
   ON CONFLICT(worker_account_id,category_id,execution_scope) DO UPDATE
    SET source_review_id=excluded.source_review_id,
        source_request_key=excluded.source_request_key,
        confirmed_at=statement_timestamp(),active=true;
 END LOOP;
 -- The CURRENT complete review replaces old per-service permission. Retain
 -- history, but deactivate obsolete modes; never manufacture a related opt-in.
 UPDATE private.taxonomy_confirmed_worker_modes_v1 old
 SET active=false
 WHERE old.worker_account_id=p_owner_account_id AND old.active
   AND NOT EXISTS(
     SELECT 1 FROM jsonb_array_elements(v_batch.result->'items') item(value)
     WHERE (item.value->>'categoryId')::uuid=old.category_id
       AND item.value->>'mode'=old.execution_scope);
 v_result:=jsonb_build_object('status','BOUND_WORKER_SERVICES',
   'workerProfileId',p_profile_id,'serviceModeCount',jsonb_array_length(v_batch.plans),
   'catalogVersion',v_batch.catalog_version,'dispatchAuthority','NONE',
   'notificationAuthority','NONE','relatedOfferAuthority','NONE');
 INSERT INTO private.work_taxonomy_worker_bindings_v1(
   owner_account_id,request_key,source_review_id,profile_id,catalog_version,result)
 VALUES(p_owner_account_id,p_request_key,p_source_review_id,p_profile_id,
   v_batch.catalog_version,v_result);
 RETURN v_result;
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_bind_reviewed_need_service(p_owner_account_id uuid, p_request_key uuid, p_source_review_id uuid, p_need_id uuid, p_need_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_existing private.work_taxonomy_need_bindings_v1%ROWTYPE;
 v_batch private.work_taxonomy_review_batches_v1%ROWTYPE;
 v_review private.ai_task_reviews%ROWTYPE;
 v_command private.ai_task_review_commands%ROWTYPE;
 v_need public.needs%ROWTYPE;
 v_plan jsonb;v_item jsonb;v_category uuid;v_scope text;v_service text;v_category_version bigint;
 v_expected_digest text;v_result jsonb;
BEGIN
 PERFORM private.closure_assert_open(p_owner_account_id);
 IF coalesce(auth.jwt()->>'role','')<>'service_role' THEN
   RAISE EXCEPTION 'NEED_BINDER_SERVICE_ROLE_REQUIRED' USING errcode='42501';
 END IF;
 IF p_owner_account_id IS NULL OR p_request_key IS NULL OR p_source_review_id IS NULL
    OR p_need_id IS NULL OR coalesce(p_need_revision,0)<1 THEN
   RAISE EXCEPTION 'NEED_BINDER_INPUT_INVALID' USING errcode='22023';
 END IF;
 SELECT * INTO v_existing FROM private.work_taxonomy_need_bindings_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key FOR UPDATE;
 IF FOUND THEN
   IF v_existing.source_review_id<>p_source_review_id OR v_existing.need_id<>p_need_id
     OR v_existing.need_revision<>p_need_revision THEN
     RAISE EXCEPTION 'NEED_BINDER_REQUEST_KEY_REUSED' USING errcode='22023';
   END IF;
   RETURN v_existing.result;
 END IF;
 SELECT * INTO v_batch FROM private.work_taxonomy_review_batches_v1
  WHERE owner_account_id=p_owner_account_id AND request_key=p_request_key
    AND source_review_id=p_source_review_id AND purpose='NEED_SERVICE' FOR SHARE;
 IF NOT FOUND OR v_batch.result->>'status'<>'COMMITTED'
   OR v_batch.result->'requiresBinding' IS DISTINCT FROM 'true'::jsonb
   OR v_batch.result->'capabilityAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR v_batch.result->'notificationAuthority' IS DISTINCT FROM '"NONE"'::jsonb
   OR jsonb_typeof(v_batch.result->'items')<>'array'
   OR jsonb_array_length(v_batch.result->'items')<>1 THEN
   RAISE EXCEPTION 'NEED_BINDER_ADMISSION_NOT_COMMITTED' USING errcode='42501';
 END IF;
 SELECT * INTO v_review FROM private.ai_task_reviews r
  WHERE r.id=p_source_review_id AND r.account_id=p_owner_account_id FOR SHARE;
 IF NOT FOUND OR v_review.envelope->>'classificationState'<>'READY'
   OR v_review.envelope->>'displayedContentDigest' IS DISTINCT FROM v_batch.review_digest
   OR v_review.envelope->'classificationCandidates' IS DISTINCT FROM v_batch.plans
   OR jsonb_array_length(coalesce(v_review.envelope->'classificationCandidates','[]'::jsonb))<>1 THEN
   RAISE EXCEPTION 'NEED_BINDER_REVIEW_NOT_BOUND' USING errcode='42501';
 END IF;
 v_expected_digest:=encode(extensions.digest(jsonb_build_object('envelope',
   v_review.envelope-'displayedContentDigest','policy',v_review.policy_binding)::text,'sha256'),'hex');
 IF v_expected_digest<>v_batch.review_digest THEN
   RAISE EXCEPTION 'NEED_BINDER_REVIEW_DIGEST_INVALID' USING errcode='42501';
 END IF;
 SELECT * INTO v_command FROM private.ai_task_review_commands c
  WHERE c.review_id=p_source_review_id AND c.account_id=p_owner_account_id
    AND c.client_request_id=p_request_key AND c.need_id=p_need_id
    AND c.need_revision=p_need_revision
    AND c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'NEED_BINDER_SAVE_REQUIRED' USING errcode='42501'; END IF;
 v_plan:=v_batch.plans->0;
 v_item:=v_batch.result->'items'->0;
 IF v_plan->>'mode' IS DISTINCT FROM v_item->>'mode'
   OR private.taxonomy_normalize_v1(v_plan->>'service')
      IS DISTINCT FROM private.taxonomy_normalize_v1(v_item->>'service')
   OR v_plan->>'action' NOT IN ('REUSE_EXISTING','CREATE_CHILD','CREATE_NEW_BRANCH')
 THEN RAISE EXCEPTION 'NEED_BINDER_CATEGORY_RECEIPT_INVALID' USING errcode='42501'; END IF;
 v_category:=(v_item->>'categoryId')::uuid;
 v_category_version:=v_batch.catalog_version;
 SELECT * INTO v_need FROM public.needs n WHERE n.id=p_need_id FOR UPDATE;
 IF NOT FOUND OR v_need.requester_account_id<>p_owner_account_id OR
    v_need.revision<>p_need_revision OR v_need.status NOT IN ('DRAFT','PUBLISHED','SELECTION') THEN
   RAISE EXCEPTION 'NEED_BINDER_CURRENT_REVISION_REQUIRED' USING errcode='PT409';
 END IF;
 v_scope:=private.taxonomy_execution_scope_v1(v_need.execution_location_mode);
 IF v_scope IS NULL OR v_scope<>v_item->>'mode'
   OR private.taxonomy_normalize_v1(v_need.category)
      <>private.taxonomy_normalize_v1(v_item->>'service')
 THEN RAISE EXCEPTION 'NEED_BINDER_SERVICE_OR_MODE_STALE' USING errcode='PT409'; END IF;
 PERFORM 1 FROM private.work_taxonomy_categories c
  JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
  WHERE c.id=v_category AND c.state='ESTABLISHED' AND m.execution_scope=v_scope;
 IF NOT FOUND THEN RAISE EXCEPTION 'NEED_BINDER_CATEGORY_RETIRED' USING errcode='42501'; END IF;
 IF v_need.category_id IS NOT NULL AND v_need.category_id<>v_category THEN
   RAISE EXCEPTION 'NEED_BINDER_CONFLICTING_EXISTING_CATEGORY' USING errcode='PT409'; END IF;
 PERFORM 1 FROM private.work_taxonomy_need_snapshots s
  WHERE s.need_id=p_need_id AND s.need_revision=p_need_revision FOR UPDATE;
 IF FOUND THEN RAISE EXCEPTION 'NEED_BINDER_EXISTING_SNAPSHOT_REVIEW_REQUIRED' USING errcode='PT409'; END IF;
 -- Same transaction: category reference + single authoritative revision
 -- snapshot + durable replay receipt. A failed write rolls all three back.
 UPDATE public.needs SET category_id=v_category WHERE id=p_need_id
    AND revision=p_need_revision AND category_id IS DISTINCT FROM v_category;
 INSERT INTO private.work_taxonomy_need_snapshots
  (need_id,need_revision,category_id,catalog_version,reviewed_by_requester,
   source,classification_state,original_category)
 VALUES(p_need_id,p_need_revision,v_category,v_category_version,true,
   'OWNER_REVIEWED_BATCH','CONFIRMED',v_need.category);
 v_result:=jsonb_build_object('status','BOUND_NEED_REVISION',
   'needId',p_need_id,'needRevision',p_need_revision,'categoryId',v_category,
   'catalogVersion',v_category_version,
   'dispatchAuthority','NONE','notificationAuthority','NONE');
 INSERT INTO private.work_taxonomy_need_bindings_v1
  (owner_account_id,request_key,source_review_id,need_id,need_revision,
   category_id,catalog_version,result)
 VALUES(p_owner_account_id,p_request_key,p_source_review_id,p_need_id,
   p_need_revision,v_category,v_category_version,v_result);
 RETURN v_result;
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_capture_gemini_turn_hints_service(p_account_id uuid, p_conversation_id uuid, p_client_request_id uuid, p_turn_id uuid, p_attempt_id uuid, p_purpose text, p_catalog_version bigint, p_proposals jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_source text;v_digest text;v_existing private.work_taxonomy_gemini_turn_hints_v1%ROWTYPE;
 v_row jsonb;v_count integer;v_seen text[]:=ARRAY[]::text[];v_normalized text;
BEGIN
 PERFORM private.closure_assert_open(p_account_id);
 -- Definer privileges alone are not authorization; require the actual JWT role.
 IF coalesce(auth.jwt()->>'role','') <> 'service_role' THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_DENIED' USING errcode='42501';
 END IF;
 IF p_account_id IS NULL OR p_conversation_id IS NULL OR
    p_client_request_id IS NULL OR p_turn_id IS NULL OR p_attempt_id IS NULL OR
    p_purpose NOT IN ('WORKER_CAPABILITY','NEED_SERVICE') OR
    coalesce(p_catalog_version,0) < 1 OR
    jsonb_typeof(p_proposals) IS DISTINCT FROM 'array' OR
    pg_column_size(p_proposals)>18000 THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_INVALID' USING errcode='22023';
 END IF;
 v_count:=jsonb_array_length(p_proposals);
 IF (p_purpose='WORKER_CAPABILITY' AND v_count NOT BETWEEN 1 AND 24)
    OR (p_purpose='NEED_SERVICE' AND v_count NOT BETWEEN 1 AND 6) THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_INVALID' USING errcode='22023';
 END IF;
 FOR v_row IN SELECT value FROM jsonb_array_elements(p_proposals) LOOP
   IF jsonb_typeof(v_row)<>'object'
      OR NOT (v_row ?& array['service','mode','action','categoryId','parentId','proposedPath','reason','catalogVersion'])
      OR (SELECT count(*) FROM jsonb_object_keys(v_row)) <> 8
      OR jsonb_typeof(v_row->'service') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'reason') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'mode') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'action') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'categoryId') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'parentId') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_row->'catalogVersion') IS DISTINCT FROM 'number'
      OR char_length(btrim(v_row->>'service')) NOT BETWEEN 3 AND 120
      OR char_length(btrim(v_row->>'reason')) NOT BETWEEN 10 AND 1000
      OR v_row->>'mode' NOT IN ('REMOTE','ON_SITE')
      OR v_row->>'action' NOT IN ('REUSE_EXISTING','CREATE_CHILD','CREATE_NEW_BRANCH')
      OR (v_row->>'catalogVersion')::bigint IS DISTINCT FROM p_catalog_version
      OR jsonb_typeof(v_row->'proposedPath')<>'array'
      OR jsonb_array_length(v_row->'proposedPath')>6
      OR (v_row->>'action'='REUSE_EXISTING' AND
          (v_row->>'categoryId' IS NULL OR v_row->>'categoryId'=''
           OR v_row->>'parentId'<>'' OR jsonb_array_length(v_row->'proposedPath')<>0))
      OR (v_row->>'action'='CREATE_CHILD' AND
          (v_row->>'categoryId'<>'' OR v_row->>'parentId' IS NULL
           OR v_row->>'parentId'='' OR jsonb_array_length(v_row->'proposedPath')<1))
      OR (v_row->>'action'='CREATE_NEW_BRANCH' AND
          (v_row->>'categoryId'<>'' OR v_row->>'parentId'<>''
           OR jsonb_array_length(v_row->'proposedPath')<1))
   THEN RAISE EXCEPTION 'TAXONOMY_CAPTURE_PLAN_INVALID' USING errcode='22023'; END IF;
   -- Identity duplicates cannot be used to smuggle another mode/service.
   -- The canonical normalizer collapses Serbian Cyrillic/Latin variants.
   v_normalized:=private.taxonomy_normalize_v1(v_row->>'service');
   IF p_purpose='WORKER_CAPABILITY' THEN v_normalized:=v_normalized||'|'||(v_row->>'mode'); END IF;
   IF v_normalized IS NULL OR char_length(v_normalized)<3 OR v_normalized=ANY(v_seen) THEN
     RAISE EXCEPTION 'TAXONOMY_CAPTURE_DUPLICATE_OR_INVALID_SERVICE' USING errcode='22023';
   END IF;
   v_seen:=array_append(v_seen,v_normalized);
 END LOOP;

 -- Only a DURABLY COMPLETED turn with the exact owner/attempt identity
 -- can produce a hint. A claimed/failed/cancelled or forged turn cannot.
 IF p_purpose='WORKER_CAPABILITY' THEN
   SELECT encode(extensions.digest(
     convert_to(s.candidate::text||'|'||s.revision::text||'|'||s.base_hash,'UTF8'),'sha256'),'hex')
   INTO v_source
   FROM private.worker_ai_turns t
   JOIN private.worker_ai_sessions s
     ON s.account_id=t.account_id AND s.conversation_id=t.conversation_id
   WHERE t.account_id=p_account_id AND t.conversation_id=p_conversation_id
     AND t.client_request_id=p_client_request_id
     AND t.turn_id=p_turn_id AND t.attempt_id=p_attempt_id
     AND t.state='SUCCEEDED';
 ELSE
   SELECT encode(extensions.digest(private.ai_task_review_source(c.id)::text,'sha256'),'hex')
   INTO v_source
   FROM private.ai_need_turn_commands t
   JOIN public.ai_conversations c ON c.id=t.conversation_id
   WHERE t.account_id=p_account_id AND t.conversation_id=p_conversation_id
     AND t.client_request_id=p_client_request_id
     AND t.turn_id=p_turn_id AND t.attempt_id=p_attempt_id
     AND t.state='SUCCEEDED' AND c.account_id=p_account_id
     AND c.purpose='NEED_INTAKE';
 END IF;
 IF v_source IS NULL THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_TURN_UNCONFIRMED' USING errcode='42501';
 END IF;
 -- A succeeded LLM turn is NOT proof that any named service is in the current
 -- worker profile. The candidate's saved skills must contain every proposed
 -- service now, including after a later correction/removal in the same turn.
 -- A partial set is permitted as an untrusted hint, but the eventual owner
 -- review will refuse READY unless it covers ALL current services.
 IF p_purpose='WORKER_CAPABILITY' AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_proposals) proposal(value)
    WHERE NOT EXISTS(
      SELECT 1 FROM private.worker_ai_sessions s,
        LATERAL jsonb_array_elements_text(s.candidate->'skills') offered(skill)
      WHERE s.account_id=p_account_id AND s.conversation_id=p_conversation_id
        AND private.taxonomy_normalize_v1(offered.skill)=
            private.taxonomy_normalize_v1(proposal.value->>'service')
    )
 ) THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_WORKER_SERVICE_NOT_OFFERED' USING errcode='22023';
 END IF;
 v_digest:=encode(extensions.digest(p_proposals::text,'sha256'),'hex');
 INSERT INTO private.work_taxonomy_gemini_turn_hints_v1(
   purpose,account_id,conversation_id,client_request_id,turn_id,attempt_id,
   source_fingerprint,catalog_version,proposals,payload_digest)
 VALUES(p_purpose,p_account_id,p_conversation_id,p_client_request_id,
   p_turn_id,p_attempt_id,v_source,p_catalog_version,p_proposals,v_digest)
 ON CONFLICT(purpose,account_id,turn_id) DO NOTHING;
 SELECT * INTO v_existing FROM private.work_taxonomy_gemini_turn_hints_v1
   WHERE purpose=p_purpose AND account_id=p_account_id AND turn_id=p_turn_id;
 IF NOT FOUND OR v_existing.client_request_id<>p_client_request_id
   OR v_existing.attempt_id<>p_attempt_id
   OR v_existing.conversation_id<>p_conversation_id
   OR v_existing.source_fingerprint<>v_source
   OR v_existing.catalog_version<>p_catalog_version
   OR v_existing.payload_digest<>v_digest
   OR v_existing.proposals IS DISTINCT FROM p_proposals THEN
   RAISE EXCEPTION 'TAXONOMY_CAPTURE_REPLAY_CONFLICT' USING errcode='22023';
 END IF;
 RETURN jsonb_build_object('action','HINT_CAPTURED','authority','NONE');
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_assign_worker_categories_service(p_worker_account_id uuid, p_category_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
  v_cat_id uuid;
  v_labels text[] := ARRAY[]::text[];
  v_label text;
  v_assigned integer := 0;
BEGIN
 PERFORM private.closure_assert_open(p_worker_account_id);
  IF p_worker_account_id IS NULL OR p_category_ids IS NULL THEN
    RAISE EXCEPTION 'WORKER_OR_CATEGORIES_NULL' USING errcode='22023';
  END IF;

  FOREACH v_cat_id IN ARRAY p_category_ids LOOP
    SELECT label INTO v_label
    FROM private.work_taxonomy_categories
    WHERE id = v_cat_id AND state <> 'RETIRED';

    IF v_label IS NOT NULL THEN
      v_labels := array_append(v_labels, v_label);

      INSERT INTO private.work_taxonomy_worker_capabilities (
        worker_account_id, category_id, confirmed_at, allow_related_offers, excluded, origin
      ) VALUES (
        p_worker_account_id, v_cat_id, statement_timestamp(), true, false, 'WORKER_CONFIRMED'
      ) ON CONFLICT (worker_account_id, category_id) DO UPDATE
        SET confirmed_at = statement_timestamp(), updated_at = statement_timestamp(), excluded = false;

      v_assigned := v_assigned + 1;
    END IF;
  END LOOP;

  -- Synchronize canonical labels into public.app_profiles.skills
  IF cardinality(v_labels) > 0 THEN
    UPDATE public.app_profiles
    SET skills = array(SELECT DISTINCT unnest(coalesce(skills, ARRAY[]::text[]) || v_labels)),
        updated_at = statement_timestamp()
    WHERE account_id = p_worker_account_id AND kind = 'WORKER';
  END IF;

  RETURN jsonb_build_object(
    'workerAccountId', p_worker_account_id,
    'assignedCount', v_assigned,
    'skills', to_jsonb(v_labels)
  );
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_set_worker_execution_modes(p_worker_profile_id uuid, p_modes text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_account uuid:=auth.uid(); v_profile public.app_profiles; v_modes text[];
BEGIN
 PERFORM private.closure_assert_open(auth.uid());
 IF v_account IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING errcode='28000'; END IF;
 IF p_worker_profile_id IS NULL OR p_modes IS NULL OR cardinality(p_modes) NOT BETWEEN 1 AND 2
   OR array_position(p_modes,NULL) IS NOT NULL
   OR NOT (p_modes <@ ARRAY['ON_SITE','REMOTE']::text[])
   OR (SELECT count(DISTINCT x) FROM unnest(p_modes) AS x)<>cardinality(p_modes)
 THEN RAISE EXCEPTION 'WORKER_EXECUTION_MODES_INVALID' USING errcode='22023'; END IF;
 SELECT p.* INTO v_profile FROM public.app_profiles p
 WHERE p.id=p_worker_profile_id
 FOR UPDATE;
 IF NOT FOUND OR v_profile.account_id IS DISTINCT FROM v_account
   OR v_profile.kind IS DISTINCT FROM 'WORKER'
 THEN RAISE EXCEPTION 'WORKER_PROFILE_NOT_OWNED' USING errcode='42501'; END IF;
 IF v_profile.profile_status NOT IN ('DRAFT','ACTIVE')
 THEN RAISE EXCEPTION 'WORKER_PROFILE_NOT_EDITABLE' USING errcode='42501'; END IF;
 v_modes:=CASE WHEN 'ON_SITE'=ANY(p_modes) AND 'REMOTE'=ANY(p_modes)
  THEN ARRAY['ON_SITE','REMOTE']::text[]
  WHEN 'ON_SITE'=ANY(p_modes) THEN ARRAY['ON_SITE']::text[]
  ELSE ARRAY['REMOTE']::text[] END;
 INSERT INTO private.worker_execution_mode_choices(worker_profile_id,worker_account_id,modes)
 VALUES(p_worker_profile_id,v_account,v_modes)
 ON CONFLICT(worker_profile_id) DO UPDATE SET modes=excluded.modes,
   confirmed_at=statement_timestamp(),updated_at=statement_timestamp()
 WHERE private.worker_execution_mode_choices.worker_account_id=v_account
   AND private.worker_execution_mode_choices.modes IS DISTINCT FROM excluded.modes;
 IF NOT EXISTS (SELECT 1 FROM private.worker_execution_mode_choices x
   WHERE x.worker_profile_id=p_worker_profile_id
   AND x.worker_account_id=v_account AND x.modes=v_modes) THEN
  RAISE EXCEPTION 'WORKER_MODE_CHOICE_CONSISTENCY_FAILED' USING errcode='42501';
 END IF;
 RETURN jsonb_build_object('workerProfileId',p_worker_profile_id,
  'modes',to_jsonb(v_modes),'confirmed',true,
  'matchingAuthority','NONE','notificationAuthority','NONE',
  'note','PREFERENCE_ONLY_UNTIL_MATCHER_INTEGRATION');
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_approve_admission(p_admission_id uuid, p_plan_digest text, p_displayed_review_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v private.work_taxonomy_admissions_v1%ROWTYPE;v_owner uuid;
BEGIN
 PERFORM private.closure_assert_open(auth.uid());
 v_owner:=auth.uid();
 IF v_owner IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING errcode='28000'; END IF;
 SELECT * INTO v FROM private.work_taxonomy_admissions_v1
  WHERE id=p_admission_id AND owner_account_id=v_owner FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_NOT_OWNED' USING errcode='42501'; END IF;
 IF v.status='COMMITTED' THEN RETURN v.result; END IF;
 IF v.expires_at<=statement_timestamp() THEN RAISE EXCEPTION 'ADMISSION_EXPIRED'; END IF;
 IF v.plan_digest IS DISTINCT FROM p_plan_digest
 OR v.source_review_digest IS DISTINCT FROM p_displayed_review_digest THEN
  RAISE EXCEPTION 'ADMISSION_DISPLAY_MISMATCH' USING errcode='42501'; END IF;
 -- This is not a second consent action. The EXISTING Save profile / Accept
 -- task review command must already have succeeded for the same review and
 -- exact idempotency/request key. A caller knowing the digest is not enough.
 IF v.purpose='WORKER_CAPABILITY' THEN
  PERFORM 1 FROM private.worker_ai_saves s
   WHERE s.review_id=v.source_review_id
     AND s.account_id=v.owner_account_id
     AND s.client_request_id=v.request_key;
 ELSE
  PERFORM 1 FROM private.ai_task_review_commands c
   WHERE c.review_id=v.source_review_id
     AND c.account_id=v.owner_account_id
     AND c.client_request_id=v.request_key
     AND c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED');
 END IF;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'ADMISSION_REVIEW_SAVE_REQUIRED' USING errcode='42501'; END IF;
 IF v.status='PENDING' THEN
   UPDATE private.work_taxonomy_admissions_v1 SET status='APPROVED',approved_at=statement_timestamp()
   WHERE id=v.id;
 END IF;
 RETURN jsonb_build_object('admissionId',v.id,'status','APPROVED');
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_commit_admission_service(p_admission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v private.work_taxonomy_admissions_v1%ROWTYPE;v_version bigint;
 v_action text;v_mode text;v_parent uuid;v_id uuid;v_label text;v_key text;
 v_existing_parent uuid;v_scope_exists boolean;v_added integer:=0;v_receipt jsonb;
 i integer;v_node_count integer;
BEGIN
 PERFORM private.closure_assert_open(owner_account_id) FROM private.work_taxonomy_admissions_v1 WHERE id=p_admission_id;
 SELECT * INTO v FROM private.work_taxonomy_admissions_v1 WHERE id=p_admission_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_NOT_FOUND' USING errcode='22023'; END IF;
 IF v.status='COMMITTED' THEN RETURN v.result; END IF;
 IF v.plan_digest IS DISTINCT FROM
    encode(extensions.digest(convert_to(v.plan::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'ADMISSION_PLAN_TAMPERED' USING errcode='42501'; END IF;
 IF v.status<>'APPROVED' OR v.approved_at IS NULL THEN
  RAISE EXCEPTION 'ADMISSION_OWNER_APPROVAL_REQUIRED' USING errcode='42501'; END IF;
 IF v.expires_at<=statement_timestamp() THEN RAISE EXCEPTION 'ADMISSION_EXPIRED'; END IF;
 -- Serialize admission writers. Old unsafe writers must be retired before live enable.
 SELECT catalog_version INTO v_version
  FROM private.work_taxonomy_control WHERE singleton FOR UPDATE;
 IF v_version<>v.catalog_version OR
    private.taxonomy_admission_fingerprint_v1()<>v.catalog_fingerprint THEN
  RAISE EXCEPTION 'ADMISSION_STALE_CATALOG_REPLAN' USING errcode='40001'; END IF;
 v_action:=v.plan->>'action';v_mode:=v.plan->>'mode';
 IF v_action='REUSE_EXISTING' THEN
  v_id:=(v.plan->>'categoryId')::uuid;
  PERFORM 1 FROM private.work_taxonomy_categories c
    JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
    WHERE c.id=v_id AND c.state='ESTABLISHED' AND m.execution_scope=v_mode;
  IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_CATEGORY_CHANGED'; END IF;
 ELSE
  IF v_action<>'CREATE_CHILD' OR jsonb_typeof(v.plan->'path')<>'array' THEN
    RAISE EXCEPTION 'ADMISSION_ACTION_UNSUPPORTED'; END IF;
  v_parent:=(v.plan->>'parentId')::uuid;
  v_node_count:=jsonb_array_length(v.plan->'path');
  IF v_node_count NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'ADMISSION_PATH_INVALID'; END IF;
  PERFORM 1 FROM private.work_taxonomy_categories c
   JOIN private.work_taxonomy_category_modes m ON m.category_id=c.id
   WHERE c.id=v_parent AND c.state='ESTABLISHED' AND m.execution_scope=v_mode;
  IF NOT FOUND THEN RAISE EXCEPTION 'ADMISSION_PARENT_CHANGED'; END IF;
  IF private.taxonomy_risk_triage_v1(v.plan->'path'->>(v_node_count-1))
     <> 'LOW_RISK_CANDIDATE' THEN RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED'; END IF;
  FOR i IN 0..v_node_count-1 LOOP
   v_label:=btrim(v.plan->'path'->>i);
   IF char_length(v_label) NOT BETWEEN 3 AND 120
      OR v_label ~ '[<>{}\\]' OR v_label ~ '[[:cntrl:]]' THEN
      RAISE EXCEPTION 'ADMISSION_NODE_INVALID' USING errcode='22023'; END IF;
   IF private.taxonomy_risk_triage_v1(v_label) IN ('BLOCKED','REVIEW_REQUIRED') THEN
     RAISE EXCEPTION 'ADMISSION_SAFETY_REVIEW_REQUIRED' USING errcode='42501'; END IF;
   v_key:=private.taxonomy_normalize_v1(v_label);
   IF char_length(v_key) NOT BETWEEN 3 AND 160 THEN
      RAISE EXCEPTION 'ADMISSION_NORMALIZATION_INVALID'; END IF;
   IF EXISTS (SELECT 1 FROM private.work_taxonomy_aliases a
     WHERE a.normalized_key=v_key) THEN
     RAISE EXCEPTION 'ADMISSION_ALIAS_COLLISION_REVIEW_REQUIRED'; END IF;
   v_id:=NULL;
   SELECT c.id,c.parent_id INTO v_id,v_existing_parent
   FROM private.work_taxonomy_categories c WHERE c.canonical_key=v_key
   FOR UPDATE;
   IF FOUND THEN
    IF v_existing_parent IS DISTINCT FROM v_parent OR
       NOT EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes
        WHERE category_id=v_id AND execution_scope=v_mode) THEN
      RAISE EXCEPTION 'ADMISSION_MEANING_OR_MODE_COLLISION_REVIEW_REQUIRED'; END IF;
   ELSE
    UPDATE private.work_taxonomy_control
      SET catalog_version=catalog_version+1,updated_at=statement_timestamp()
      WHERE singleton RETURNING catalog_version INTO v_version;
    INSERT INTO private.work_taxonomy_categories
      (canonical_key,label,parent_id,state,source,catalog_version)
    VALUES(v_key,v_label,v_parent,'ESTABLISHED','AI_REVIEWED',v_version)
    RETURNING id INTO v_id;
    INSERT INTO private.work_taxonomy_category_modes(category_id,execution_scope,source_ref)
     VALUES(v_id,v_mode,'OWNER_APPROVED_ADMISSION_V1');
    INSERT INTO private.work_taxonomy_audit
      (action,category_id,normalized_key,catalog_version,source_ref)
    VALUES('AUTO_CREATED',v_id,v_key,v_version,'OWNER_APPROVED_ADMISSION_V1:'||v.id::text);
    v_added:=v_added+1;
   END IF;
   v_parent:=v_id;
  END LOOP;
 END IF;
 v_receipt:=jsonb_build_object('admissionId',v.id,'categoryId',v_id,
   'catalogVersion',v_version,'createdCount',v_added,'status','COMMITTED',
   'capabilityAuthority','NONE','notificationAuthority','NONE',
   'requiresPostSaveBinding',true);
 UPDATE private.work_taxonomy_admissions_v1
  SET status='COMMITTED',committed_at=statement_timestamp(),result=v_receipt
  WHERE id=v.id;
 RETURN v_receipt;
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_finalize_reviewed_batch_service(p_outbox_id uuid, p_lease_token uuid, p_error_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v private.work_taxonomy_review_outbox_v1%ROWTYPE;v_receipt jsonb;
 v_status text;v_retry timestamptz;
BEGIN
 PERFORM private.closure_assert_open(owner_account_id) FROM private.work_taxonomy_review_outbox_v1 WHERE id=p_outbox_id;
 SELECT * INTO v FROM private.work_taxonomy_review_outbox_v1
 WHERE id=p_outbox_id FOR UPDATE;
 IF NOT FOUND OR v.state<>'CLAIMED' OR v.lease_token IS DISTINCT FROM p_lease_token
    OR v.lease_until<=statement_timestamp()
 THEN RAISE EXCEPTION 'OUTBOX_STALE_LEASE' USING errcode='42501'; END IF;
 IF p_error_code IS NULL THEN
  SELECT b.result INTO v_receipt FROM private.work_taxonomy_review_batches_v1 b
  WHERE b.owner_account_id=v.owner_account_id AND b.request_key=v.request_key
    AND b.source_review_id=v.source_review_id AND b.purpose=v.purpose
    AND b.plans IS NOT DISTINCT FROM v.plans;
  IF v_receipt IS NULL OR v_receipt->>'status'<>'COMMITTED' THEN
   RAISE EXCEPTION 'OUTBOX_COMMIT_RECEIPT_MISSING' USING errcode='42501'; END IF;
  v_status:='COMMITTED';v_retry:=statement_timestamp();
 ELSE
  IF p_error_code !~ '^[A-Z][A-Z0-9_]{2,79}$' THEN
   RAISE EXCEPTION 'OUTBOX_ERROR_CODE_INVALID' USING errcode='22023'; END IF;
  -- Invalid/stale semantic plans require re-planning or internal review.
  -- Network/timeouts are retryable without consuming any new owner consent.
  IF p_error_code IN('TIMEOUT','NETWORK_UNAVAILABLE','TEMPORARY_UNAVAILABLE')
    AND v.attempts<5 THEN
   v_status:='RETRY';
   v_retry:=statement_timestamp()+make_interval(secs=>LEAST(1800,15*power(2,LEAST(v.attempts,7)))::integer);
  ELSE
   v_status:='REVIEW_REQUIRED';v_retry:=statement_timestamp();
  END IF;
 END IF;
 UPDATE private.work_taxonomy_review_outbox_v1
 SET state=v_status,lease_token=NULL,lease_until=NULL,retry_after=v_retry,
   error_code=p_error_code,result=v_receipt,updated_at=statement_timestamp()
 WHERE id=v.id;
 RETURN jsonb_build_object('status',v_status,'outboxId',v.id);
END $function$;

CREATE OR REPLACE FUNCTION private.sync_worker_skills_to_taxonomy_capabilities(p_account_id uuid, p_skills text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_saved_skills text[];
 v_skill text;v_norm text;v_cat_id uuid;v_match_count integer;
 v_retained_ids uuid[]:=ARRAY[]::uuid[];
 v_unmapped_labels text[]:=ARRAY[]::text[];
 v_revoked integer:=0;v_revoked_acceptances integer:=0;
BEGIN
 IF private.closure_taxonomy_profile_erasing_v1(p_account_id) THEN
 RETURN jsonb_build_object('success',true,'workerAccountId',p_account_id,'assignedCount',0,'assignedCategoryIds','[]'::jsonb,
 'retainedExistingCategoryCount',0,'retainedExistingCategoryIds','[]'::jsonb,'revokedCount',0,'revokedRelatedAcceptances',0,
 'unmappedSkillLabels','[]'::jsonb,'openNeedsRequeued',0,'newCapabilityAuthority','NONE','notificationAuthority','NONE');END IF;
 PERFORM private.closure_assert_open(p_account_id);
 IF p_account_id IS NULL THEN
   RAISE EXCEPTION 'WORKER_ACCOUNT_REQUIRED' USING errcode='22023';
 END IF;
 SELECT COALESCE(p.skills,ARRAY[]::text[]) INTO v_saved_skills
 FROM public.app_profiles p
 WHERE p.account_id=p_account_id AND p.kind='WORKER'
 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'WORKER_PROFILE_REQUIRED' USING errcode='55000'; END IF;
 IF v_saved_skills IS DISTINCT FROM COALESCE(p_skills,ARRAY[]::text[]) THEN
   RAISE EXCEPTION 'TAXONOMY_PROFILE_SKILLS_MISMATCH' USING errcode='22023';
 END IF;
 -- A canonical/registered-alias match is used ONLY to decide which already
 -- confirmed capability is still mentioned by the worker. This is not consent.
 -- No invented ON_SITE mode, no nearest-parent inference and no new records.
 FOREACH v_skill IN ARRAY v_saved_skills LOOP
   v_skill:=btrim(COALESCE(v_skill,''));
   IF char_length(v_skill) NOT BETWEEN 3 AND 120 THEN
     v_unmapped_labels:=array_append(v_unmapped_labels,v_skill);
     CONTINUE;
   END IF;
   v_norm:=private.taxonomy_normalize_v1(v_skill);
   SELECT count(DISTINCT c.id),min(c.id::text)::uuid
      INTO v_match_count,v_cat_id
   FROM private.work_taxonomy_categories c
   WHERE c.state='ESTABLISHED'
     AND EXISTS(SELECT 1 FROM private.work_taxonomy_category_modes m
       WHERE m.category_id=c.id)
     AND (c.canonical_key=v_norm OR EXISTS(
       SELECT 1 FROM private.work_taxonomy_aliases a
       WHERE a.category_id=c.id AND a.normalized_key=v_norm));
   IF v_match_count<>1 OR v_cat_id IS NULL THEN
     v_unmapped_labels:=array_append(v_unmapped_labels,v_skill);
     CONTINUE;
   END IF;
   IF NOT v_cat_id=ANY(v_retained_ids) THEN
     v_retained_ids:=array_append(v_retained_ids,v_cat_id);
   END IF;
 END LOOP;
 -- Explicitly removed or now-ambiguous worker services lose existing legacy
 -- eligibility and related opt-ins. Retained rows are NOT refreshed/revived.
 UPDATE private.work_taxonomy_worker_capabilities w
 SET excluded=true,allow_related_offers=false,updated_at=statement_timestamp()
 WHERE w.worker_account_id=p_account_id
   AND NOT (w.category_id=ANY(v_retained_ids))
   AND (NOT w.excluded OR w.allow_related_offers);
 GET DIAGNOSTICS v_revoked=ROW_COUNT;
 DELETE FROM private.work_taxonomy_related_acceptances a
 WHERE a.worker_account_id=p_account_id
   AND NOT (a.source_category_id=ANY(v_retained_ids));
 GET DIAGNOSTICS v_revoked_acceptances=ROW_COUNT;
 -- Deliberately NO requeue: Save is not a taxonomy binder receipt. A signed
 -- reconciler may later schedule matching only after both sides are bound.
 RETURN jsonb_build_object(
   'success',true,'workerAccountId',p_account_id,
   'assignedCount',0,'assignedCategoryIds','[]'::jsonb,
   'retainedExistingCategoryCount',cardinality(v_retained_ids),
   'retainedExistingCategoryIds',to_jsonb(v_retained_ids),
   'revokedCount',v_revoked,
   'revokedRelatedAcceptances',v_revoked_acceptances,
   'unmappedSkillLabels',to_jsonb(v_unmapped_labels),
   'openNeedsRequeued',0,
   'newCapabilityAuthority','NONE',
   'notificationAuthority','NONE'
 );
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_claim_reviewed_batches_service(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v_docs jsonb;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 20 THEN
  RAISE EXCEPTION 'OUTBOX_CLAIM_LIMIT_INVALID' USING errcode='22023'; END IF;
 WITH candidates AS MATERIALIZED (
  SELECT id,owner_account_id FROM private.work_taxonomy_review_outbox_v1
  WHERE NOT private.closure_account_restricted(owner_account_id) AND ((state IN ('PENDING','RETRY') AND retry_after<=statement_timestamp())
     OR (state='CLAIMED' AND lease_until<statement_timestamp()))
  ORDER BY created_at,id LIMIT p_limit
 ), admitted AS MATERIALIZED (SELECT id FROM candidates WHERE private.closure_taxonomy_try_owner_v1(owner_account_id)),
 selected AS (SELECT q.id FROM private.work_taxonomy_review_outbox_v1 q JOIN admitted a ON a.id=q.id WHERE (q.state IN ('PENDING','RETRY') AND q.retry_after<=statement_timestamp()) OR (q.state='CLAIMED' AND q.lease_until<statement_timestamp()) FOR UPDATE OF q SKIP LOCKED),
 claimed AS (
  UPDATE private.work_taxonomy_review_outbox_v1 q
   SET state='CLAIMED',attempts=q.attempts+1,
       lease_token=gen_random_uuid(),lease_until=statement_timestamp()+interval '2 minutes',
       updated_at=statement_timestamp()
   FROM selected s WHERE q.id=s.id
   RETURNING q.id,q.owner_account_id,q.request_key,q.source_review_id,
    q.purpose,q.plans,q.lease_token,q.attempts
 )
 SELECT coalesce(jsonb_agg(jsonb_build_object(
  'id',id,'ownerAccountId',owner_account_id,'requestKey',request_key,
  'sourceReviewId',source_review_id,'purpose',purpose,'plans',plans,
  'leaseToken',lease_token,'attempts',attempts) ORDER BY id),'[]'::jsonb)
 INTO v_docs FROM claimed;
 RETURN v_docs;
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_bind_ready_reviews_service(p_limit integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE
 v_enabled boolean;
 v_q private.work_taxonomy_review_outbox_v1%ROWTYPE;
 v_profile_id uuid;v_need_id uuid;v_need_revision integer;
 v_receipt jsonb;v_sqlstate text;v_attempts integer;
 v_claimed integer:=0;v_bound integer:=0;v_review_required integer:=0;v_retry integer:=0;
BEGIN
 IF coalesce(auth.jwt()->>'role','')<>'service_role'
 THEN RAISE EXCEPTION 'BINDING_TICK_SERVICE_ROLE_REQUIRED' USING errcode='42501'; END IF;
 IF p_limit NOT BETWEEN 1 AND 5
 THEN RAISE EXCEPTION 'BINDING_TICK_LIMIT_INVALID' USING errcode='22023'; END IF;
 SELECT enabled INTO v_enabled FROM private.work_taxonomy_binding_control_v1 WHERE singleton;
 IF v_enabled IS DISTINCT FROM true THEN
  RETURN jsonb_build_object('kind','BINDING_DISABLED','claimed',0,
   'bound',0,'retry',0,'reviewRequired',0,
   'dispatchAuthority','NONE','notificationAuthority','NONE');
 END IF;
 FOR v_q IN
  WITH candidates AS MATERIALIZED (SELECT q.id,q.owner_account_id FROM private.work_taxonomy_review_outbox_v1 q
  WHERE NOT private.closure_account_restricted(q.owner_account_id) AND q.state='COMMITTED'
    AND q.binding_state IN ('PENDING','RETRY')
    AND q.binding_retry_after<=statement_timestamp()
  ORDER BY q.created_at,q.id
  LIMIT p_limit), admitted AS MATERIALIZED (SELECT id FROM candidates WHERE private.closure_taxonomy_try_owner_v1(owner_account_id))
  SELECT q.* FROM private.work_taxonomy_review_outbox_v1 q JOIN admitted a ON a.id=q.id WHERE q.state='COMMITTED' AND q.binding_state IN ('PENDING','RETRY') AND q.binding_retry_after<=statement_timestamp() FOR UPDATE OF q SKIP LOCKED
 LOOP
  v_claimed:=v_claimed+1;v_attempts:=v_q.binding_attempts+1;
  BEGIN
   IF v_q.purpose='WORKER_CAPABILITY' THEN
    SELECT (r.envelope->>'profileId')::uuid INTO v_profile_id
    FROM private.worker_ai_reviews r
    WHERE r.id=v_q.source_review_id AND r.account_id=v_q.owner_account_id
      AND r.envelope->>'classificationState'='READY';
    IF v_profile_id IS NULL THEN
     RAISE EXCEPTION 'BINDING_SIGNED_WORKER_REVIEW_MISSING' USING errcode='42501';
    END IF;
    -- The binder rechecks original owner, Save receipt, digest, mode and current
    -- profile under lock. Never use an Edge-supplied profile or AI-proposed mode.
    v_receipt:=public.rpc_taxonomy_bind_reviewed_worker_service(
      v_q.owner_account_id,v_q.request_key,v_q.source_review_id,v_profile_id);
   ELSIF v_q.purpose='NEED_SERVICE' THEN
    SELECT c.need_id,c.need_revision INTO v_need_id,v_need_revision
    FROM private.ai_task_review_commands c
    WHERE c.review_id=v_q.source_review_id AND c.account_id=v_q.owner_account_id
      AND c.client_request_id=v_q.request_key
      AND c.state IN('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED')
    ORDER BY c.created_at DESC LIMIT 1;
    IF v_need_id IS NULL OR v_need_revision IS NULL THEN
     RAISE EXCEPTION 'BINDING_ACCEPTED_NEED_NOT_READY' USING errcode='PT409';
    END IF;
    v_receipt:=public.rpc_taxonomy_bind_reviewed_need_service(
      v_q.owner_account_id,v_q.request_key,v_q.source_review_id,
      v_need_id,v_need_revision);
   ELSE
    RAISE EXCEPTION 'BINDING_PURPOSE_INVALID' USING errcode='22023';
   END IF;
   IF v_receipt->>'status' NOT IN('BOUND_WORKER_SERVICES','BOUND_NEED_REVISION')
     OR v_receipt->>'notificationAuthority'<>'NONE'
     OR v_receipt->>'dispatchAuthority'<>'NONE' THEN
     RAISE EXCEPTION 'BINDING_RECEIPT_PROTOCOL_INVALID' USING errcode='42501';
   END IF;
   UPDATE private.work_taxonomy_review_outbox_v1
    SET binding_state='BOUND',binding_attempts=v_attempts,
      binding_error_code=NULL,binding_result=v_receipt,updated_at=statement_timestamp()
    WHERE id=v_q.id;
   v_bound:=v_bound+1;
  EXCEPTION WHEN OTHERS THEN
   -- Per-item subtransaction rolls back any partly written binder receipt,
   -- capability or snapshot. Catalog commit and prior Save remain untouched.
   GET STACKED DIAGNOSTICS v_sqlstate=RETURNED_SQLSTATE;
   IF v_sqlstate IN('PT409','40001','40P01','55P03','57014') AND v_attempts<5 THEN
    UPDATE private.work_taxonomy_review_outbox_v1
     SET binding_state='RETRY',binding_attempts=v_attempts,
       binding_error_code='BINDING_STALE_OR_BUSY',
       binding_retry_after=statement_timestamp()
         +make_interval(secs=>LEAST(900,15*power(2,LEAST(v_attempts,5)))::integer),
       updated_at=statement_timestamp()
     WHERE id=v_q.id;
    v_retry:=v_retry+1;
   ELSE
    UPDATE private.work_taxonomy_review_outbox_v1
     SET binding_state='REVIEW_REQUIRED',binding_attempts=v_attempts,
       binding_error_code='BINDING_REVIEW_REQUIRED',
       updated_at=statement_timestamp()
     WHERE id=v_q.id;
    v_review_required:=v_review_required+1;
   END IF;
  END;
 END LOOP;
 RETURN jsonb_build_object('kind','BINDING_ONLY_TICK','claimed',v_claimed,
  'bound',v_bound,'retry',v_retry,'reviewRequired',v_review_required,
  'dispatchAuthority','NONE','notificationAuthority','NONE');
END $function$;

CREATE OR REPLACE FUNCTION public.rpc_taxonomy_reconcile_reviewed_outbox_service(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v_enabled boolean;v_count integer;
BEGIN
 IF p_limit NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'OUTBOX_RECOVERY_LIMIT_INVALID' USING errcode='22023'; END IF;
 SELECT enabled INTO v_enabled FROM private.work_taxonomy_review_outbox_control_v1
 WHERE singleton;
 IF v_enabled IS DISTINCT FROM true THEN RETURN 0; END IF;
 WITH accepted AS (
   SELECT s.account_id,s.client_request_id,s.review_id,
      'WORKER_CAPABILITY'::text AS purpose,
      w.envelope->'classificationCandidates' AS plans,s.created_at
   FROM private.worker_ai_saves s
   JOIN private.worker_ai_reviews w ON w.id=s.review_id AND w.account_id=s.account_id
   WHERE w.envelope->'canAccept'='true'::jsonb
     AND w.envelope->>'classificationCatalogFingerprint' IS NOT NULL
     AND CASE WHEN jsonb_typeof(w.envelope->'classificationCandidates')='array'
       THEN jsonb_array_length(w.envelope->'classificationCandidates') BETWEEN 1 AND 24
       ELSE false END
   UNION ALL
   SELECT c.account_id,c.client_request_id,c.review_id,
      'NEED_SERVICE'::text AS purpose,
      t.envelope->'classificationCandidates' AS plans,c.created_at
   FROM private.ai_task_review_commands c
   JOIN private.ai_task_reviews t ON t.id=c.review_id AND t.account_id=c.account_id
   WHERE c.state IN ('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED')
     AND t.envelope->'canAccept'='true'::jsonb
     AND t.envelope->>'classificationCatalogFingerprint' IS NOT NULL
     AND CASE WHEN jsonb_typeof(t.envelope->'classificationCandidates')='array'
       THEN jsonb_array_length(t.envelope->'classificationCandidates')=1
       ELSE false END
 ),
 missing AS MATERIALIZED (
   SELECT a.* FROM accepted a
   WHERE NOT private.closure_account_restricted(a.account_id) AND NOT EXISTS (SELECT 1 FROM private.work_taxonomy_review_outbox_v1 q
     WHERE q.owner_account_id=a.account_id AND q.request_key=a.client_request_id)
   ORDER BY a.created_at,a.review_id LIMIT p_limit
 ),
 admitted AS MATERIALIZED (SELECT * FROM missing WHERE private.closure_taxonomy_try_owner_v1(account_id)),
 inserted AS (
   INSERT INTO private.work_taxonomy_review_outbox_v1
     (owner_account_id,request_key,source_review_id,purpose,plans)
   SELECT account_id,client_request_id,review_id,purpose,plans FROM admitted
   ON CONFLICT(owner_account_id,request_key) DO NOTHING
   RETURNING id
 )
 SELECT count(*)::integer INTO v_count FROM inserted;
 RETURN v_count;
END $function$;

CREATE OR REPLACE FUNCTION private.taxonomy_reconcile_pending_reviews_v1(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private'
AS $function$
DECLARE v_count integer;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION 'PENDING_LEDGER_LIMIT_INVALID' USING errcode='22023'; END IF;
 IF (SELECT enabled FROM private.work_taxonomy_pending_control_v1 WHERE singleton) IS DISTINCT FROM true
 THEN RETURN 0; END IF;
 WITH saved AS (
   SELECT s.account_id,s.client_request_id,s.review_id,'WORKER_CAPABILITY'::text purpose,
     r.envelope,s.created_at
   FROM private.worker_ai_saves s JOIN private.worker_ai_reviews r
    ON r.id=s.review_id AND r.account_id=s.account_id
   UNION ALL
   SELECT c.account_id,c.client_request_id,c.review_id,'NEED_SERVICE'::text,
     r.envelope,c.created_at
   FROM private.ai_task_review_commands c JOIN private.ai_task_reviews r
    ON r.id=c.review_id AND r.account_id=c.account_id
   WHERE c.state IN('ACCEPTED','EVALUATING','EVALUATED','PUBLISHED')
 ),
 missing AS MATERIALIZED (
   SELECT * FROM saved s WHERE NOT private.closure_account_restricted(s.account_id) AND
    s.envelope->'canAccept'='true'::jsonb
    AND s.envelope->>'classificationState' IN
     ('PENDING_CLASSIFICATION','SERVICE_MODE_CONFIRMATION_REQUIRED','REVIEW_REQUIRED',
      'CATALOG_UNAVAILABLE','STALE_CATALOG')
    AND coalesce(s.envelope->>'displayedContentDigest','') ~ '^[a-f0-9]{64}$'
    AND NOT EXISTS(SELECT 1 FROM private.work_taxonomy_pending_reviews_v1 p
      WHERE p.owner_account_id=s.account_id AND p.request_key=s.client_request_id)
   ORDER BY created_at,review_id LIMIT p_limit
 ),
 admitted AS MATERIALIZED (SELECT * FROM missing WHERE private.closure_taxonomy_try_owner_v1(account_id)),
 ins AS (
   INSERT INTO private.work_taxonomy_pending_reviews_v1
    (owner_account_id,request_key,source_review_id,purpose,classification_state,saved_at)
   SELECT account_id,client_request_id,review_id,purpose,envelope->>'classificationState',created_at
   FROM admitted ON CONFLICT(owner_account_id,request_key) DO NOTHING RETURNING id
 )
 SELECT count(*)::integer INTO v_count FROM ins;
 RETURN v_count;
END $function$;

CREATE OR REPLACE FUNCTION private.data_export_projection_sha_v5()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$ select encode(extensions.digest(convert_to(string_agg(signature||':'||md5(replace(p.prosrc,E'\r\n',E'\n')),E'\n' order by signature),'UTF8'),'sha256'),'hex') from unnest(array['private.data_export_dataset_catalog()','private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)','private.data_export_scalar_v5(jsonb,text)','private.data_export_array_v5(jsonb,text)','private.data_export_worker_candidate_v5(jsonb)','private.data_export_task_facts_v5(jsonb)','private.closure_taxonomy_inventory_v1()','private.closure_taxonomy_semantic_keys_v1()','private.closure_taxonomy_reset_sections_v1()','private.closure_taxonomy_scope_v1(text)','private.closure_taxonomy_semantic_v1(jsonb)','private.closure_taxonomy_project_v1(text,jsonb,uuid)','private.closure_taxonomy_export_rows_v1(uuid)','private.closure_taxonomy_export_catalog_v1()']) signature join pg_proc p on p.oid=to_regprocedure(signature) having count(*)=14 $function$;

CREATE OR REPLACE FUNCTION private.closure_source_digest_v5()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 select encode(extensions.digest(convert_to(private.closure_schema_digest_v5_139()||':'||private.closure_erasure_program_digest_v5()||':'||private.agreement_invalidation_surface_v1()||':'||private.agreement_voice_surface_v1()||':'||string_agg(signature||':'||md5(p.prosrc),E'\n' order by signature),'UTF8'),'sha256'),'hex')
 from unnest(array['private.capture_agreement_media_v5(uuid,integer,boolean)','private.capture_case_media_v5(text,uuid,bigint,uuid,uuid,uuid,uuid)',
 'private.media_owner_protected_v5(uuid)','private.media_evidence_key_v5(uuid)','private.closure_blockers_v5(uuid)','private.resolve_media_snapshot_v5(uuid,jsonb)',
 'private.support_auth_v5(uuid)','private.support_operator_key_v5()','private.support_command_key_v5(uuid,uuid)',
 'private.support_safe_exit_v5(uuid,uuid)','private.support_operator_revision_v5(uuid)','private.support_immutable_v5()',
 'private.support_case_guard_v5()','private.support_command_document_v5(uuid,uuid)',
 'public.rpc_support_read_command_v5(uuid,uuid)','public.rpc_support_cancel_command_v5(uuid,uuid)',
 'private.support_reference_v5(uuid,jsonb)','private.support_capture_media_v5(uuid,integer,jsonb)',
 'private.support_safety_case_v5(private.safety_reports,boolean)','private.support_safety_capture_v5()','private.support_safety_closure_v5()',
 'private.support_event_document_v5(private.support_events_v5)','private.support_decision_document_v5(private.support_decisions_v5)',
